const tg=window.Telegram?.WebApp;
tg?.ready();tg?.expand();
const app=document.querySelector('#app');
const state={tab:'home',playView:'games',communityTab:'people',cityFilter:'all',trainingCity:'all',notifications:[],notificationUnread:0,ratingHistory:[],progress:null,filter:'all',when:'all',courts:[],genderFilter:'all',ratingOnly:false,myLevelOnly:false,availableOnly:false,trainingSport:'all',trainingGender:'all',trainingCourts:[],trainingFormat:'all',games:[],catalog:{coaches:[],courts:[]},trainings:[],news:[],location:null,locationStatus:'',geoPolls:0,weather:[],weatherCity:'Краснодар',weatherStatus:'loading',weatherFetched:false,people:[],peopleMode:'all',peopleQuery:'',peopleOffset:0,peopleMore:false,inbox:[],unread:0,leaderboard:[],leaderboardSport:'tennis',clubDate:'',clubCalendar:[],clubBookings:[],clubPhotoData:null,bookingCourtId:null,courtCity:'all',courtSport:'all',marathon:null,adminClubs:[],adminStats:null,adminUsers:[],adminMessages:[],adminListings:{games:[],trainings:[]},adminTab:'overview',previewRole:'player',previewTab:'home',eventIndex:0,adminQuery:'',adminClubId:null,adminCalendar:[],confirmModeration:null,pendingBlock:null,chat:null,chatThreads:null,history:[],me:null,config:{},detail:null,trainingDetail:null,userProfile:null,form:'',profilePhotoData:null,avatarId:null,registrationStep:1,registrationRole:null,registrationDraft:null,pendingGame:null,loading:true};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(iso,opts)=>new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',...opts}).format(new Date(iso));
const day=iso=>fmt(iso,{day:'numeric',month:'short'});
const hour=iso=>fmt(iso,{hour:'2-digit',minute:'2-digit'});
const dayKey=iso=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(iso));
const tomorrow=()=>{const d=new Date(Date.now()+86400000);return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)};
let demoId=localStorage.getItem('tennis-go-demo-id');if(!demoId){demoId='demo-'+crypto.randomUUID();localStorage.setItem('tennis-go-demo-id',demoId);}
function headers(){return tg?.initData?{'Authorization':'tma '+tg.initData}:{'X-Demo-User':demoId,'X-Demo-Name':encodeURIComponent('Роман')};}
async function api(route,method='GET',payload){const res=await fetch('/api'+route,{method,headers:{...headers(),...(payload?{'Content-Type':'application/json'}:{})},body:payload?JSON.stringify(payload):undefined});const data=await res.json();if(!res.ok)throw new Error(data.error||'Ошибка сети');return data;}
function toast(message){document.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.textContent=message;document.body.append(n);setTimeout(()=>n.remove(),3300);tg?.HapticFeedback?.notificationOccurred?.('success');}
async function refresh(){const me=(await api('/me')).user;state.me=me;if(me.role==='club'&&!me.isAdmin){state.clubDate ||= dayKey(Date.now());const data=await api('/club/calendar?date='+state.clubDate);state.clubCalendar=data.reservations||[];return;}const [g,c,t,i,n,h,p,b,event,news]=await Promise.all([api('/games'),api('/catalog'),api('/trainings'),api('/inbox'),api('/notifications'),api('/ratings/history'),api('/progress'),api('/court-bookings'),api('/events/marathon'),api('/news')]);state.games=g.games;state.catalog=c;state.trainings=t.trainings;state.inbox=i.threads||[];state.unread=i.unread||0;state.notifications=n.items||[];state.notificationUnread=n.unread||0;state.ratingHistory=h.events||[];state.progress=p;state.clubBookings=b.bookings||[];state.marathon=event;state.news=news.items||[];if(!state.weatherFetched){state.weatherFetched=true;loadWeather();}}
async function loadWeather(){try{const city=state.cityFilter!=='all'?state.cityFilter:state.trainingCity!=='all'?state.trainingCity:'Краснодар';const w=await api('/weather?city='+encodeURIComponent(city));state.weatherCity=city;state.weather=w.hours||[];state.weatherStatus=w.status||'unavailable';}catch{state.weather=[];state.weatherStatus='unavailable';}if(!state.loading&&state.me?.registered&&!state.form&&!state.chat)render();}
async function loadInbox(updatePage=true){const data=await api('/inbox');state.inbox=data.threads||[];state.unread=data.unread||0;const badge=document.querySelector('#chat-badge');if(badge){badge.textContent=state.unread||'';badge.hidden=!state.unread;}if(updatePage&&state.tab==='chat'&&!state.chat)render();}
async function loadPeople(reset=false){const offset=reset?0:state.peopleOffset,search=state.peopleQuery,mode=state.peopleMode;const data=await api('/users?q='+encodeURIComponent(search)+'&offset='+offset+(mode==='coach'?'&role=coach':''));if(search!==state.peopleQuery||mode!==state.peopleMode)return;state.people=reset?data.users:[...state.people,...data.users];state.peopleOffset=offset+data.users.length;state.peopleMore=!!data.hasMore;render();}
async function loadLeaderboard(){const data=await api('/leaderboard?sport='+state.leaderboardSport);state.leaderboard=data.players||[];render();}
async function loadAdmin(tab=state.adminTab){if(!state.me?.isAdmin)return;state.adminTab=tab;if(tab==='overview')state.adminStats=await api('/admin/stats');else if(tab==='users')state.adminUsers=(await api('/admin/users?q='+encodeURIComponent(state.adminQuery))).users;else if(tab==='messages')state.adminMessages=(await api('/admin/messages')).messages;else if(tab==='clubs')state.adminClubs=(await api('/admin/clubs')).clubs;else if(['games','trainings'].includes(tab))state.adminListings=await api('/admin/listings');}
const avatarChoices=[['male-serve','Подача','Мужские'],['male-cap','Кепка','Мужские'],['male-court','У сетки','Мужские'],['female-serve','Подача','Женские'],['female-cap','Козырёк','Женские'],['female-court','У сетки','Женские']];
function tennisAvatar(id){return `<span class="tennis-avatar avatar-sprite avatar-${id}" role="img" aria-label="Мультяшная теннисная аватарка"></span>`;}
function avatar(u){return u?.photoData?`<img src="${esc(u.photoData)}" alt="Фото профиля">`:u?.avatarId&&avatarChoices.some(([id])=>id===u.avatarId)?tennisAvatar(u.avatarId):esc((u?.name||'Р').slice(0,1).toUpperCase());}
function participantStrip(members){return members.length?`<span class="participant-strip" aria-label="Записались: ${esc(members.map(m=>m.name).join(', '))}">${members.slice(0,4).map(m=>`<span class="participant-mini">${avatar(m)}</span>`).join('')}${members.length>4?`<span class="participant-more">+${members.length-4}</span>`:''}</span>`:'<span class="participant-none">Пока нет записавшихся</span>';}
function participantRows(members){return members.length?members.map(m=>`<button class="participant-row" data-user="${esc(m.id)}"><span class="avatar">${avatar(m)}</span><strong>${esc(m.name)}</strong><span class="participant-next">Профиль →</span></button>`).join(''):'<p class="muted">Пока никто не записался.</p>';}
function requestPanel(kind,item){const requests=item.requests||[];return requests.length?`<div class="form-card join-requests"><h3>Заявки на участие · ${requests.length}</h3>${requests.map(user=>`<div class="request-row"><button class="request-person" data-user="${esc(user.id)}"><span class="avatar">${avatar(user)}</span>${esc(user.name)}</button><span class="request-actions"><button class="small-btn" data-request-decision="approve" data-request-kind="${kind}" data-request-id="${esc(item.id)}" data-request-user="${esc(user.id)}">Принять</button><button class="small-btn outline" data-request-decision="reject" data-request-kind="${kind}" data-request-id="${esc(item.id)}" data-request-user="${esc(user.id)}">Отклонить</button></span></div>`).join('')}</div>`:'';}
function genderName(value){return value==='female'?'женщины':value==='male'?'мужчины':'любой пол';}
function padelIcon(){return `<svg class="sport-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-label="Ракетка для падела" role="img"><path d="M12 2.2C6.9 2.2 4 5.7 4 10c0 3.7 2.3 6.4 5.7 7.2l.9.2 1.4 1.6 1.8-1.7-.9-1.2c4-1.3 6.1-4.2 6.1-8.1 0-4.3-2.7-7.8-7-7.8Z"/><path d="m12 19 3.8 3 1.5-1.6-3.5-3.1"/><circle cx="9" cy="7" r=".8"/><circle cx="13" cy="7" r=".8"/><circle cx="7.5" cy="11" r=".8"/><circle cx="11.5" cy="11" r=".8"/><circle cx="15.5" cy="11" r=".8"/><circle cx="10" cy="14.5" r=".8"/><circle cx="14" cy="14.5" r=".8"/></svg>`;}
function logo(){return `<header class="top"><span class="brand-logo"><img src="/assets/tennis-go-approved-logo.png" alt="Tennis GO"></span><span class="top-spacer"></span>${state.me?.registered&&state.me.role!=='club'?`<button class="notification-button" data-notifications aria-label="Уведомления">🔔${state.notificationUnread?`<b>${state.notificationUnread}</b>`:''}</button>`:''}<span class="city-pill">⌖ ${esc(state.me?.city||'Краснодар')}</span><span class="avatar">${avatar(state.me)}</span></header>`;}
function nav(){const ball='<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="12" r="9"/><path d="M6.2 5.1c4.4 3.8 4.4 10 0 13.8M17.8 5.1c-4.4 3.8-4.4 10 0 13.8"/></svg>',bubble='<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M20 11.5a8 8 0 0 1-8 8 9 9 0 0 1-3.8-.8L4 20l1.3-4.2A8 8 0 1 1 20 11.5Z"/><path d="M8 11.5h8"/></svg>';return `<nav class="nav" aria-label="Основное меню">${[['home','⌂','Главная'],['play',ball,'Играть'],['chat',bubble,'Чат'],['profile','<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="7.5" r="3.5"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></svg>','Профиль']].map(([id,icon,label])=>`<button data-tab="${id}" class="${state.tab===id?'active':''}"><i>${icon}</i>${label}${id==='chat'?`<span id="chat-badge" class="nav-unread" ${state.unread?'':'hidden'}>${state.unread||''}</span>`:''}</button>`).join('')}</nav>`;}
function contactFooter(){return `<p class="footer-note contact-footer">Связаться с нами: <a href="https://t.me/RVL233" target="_blank" rel="noopener noreferrer">Telegram @RVL233</a></p>`;}
function quickIcon(type){const paths={news:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 7h6v5H7zM16 8h2M16 11h2M7 16h11M7 18h11"/>',community:'<circle cx="12" cy="7" r="3"/><circle cx="4.5" cy="9" r="2"/><circle cx="19.5" cy="9" r="2"/><path d="M6 20v-2a6 6 0 0 1 12 0v2M1 18v-2a3.5 3.5 0 0 1 3.5-3.5M23 18v-2a3.5 3.5 0 0 0-3.5-3.5"/>',court:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="M12 4v16M2 12h20M6 4v5m0 6v5m12-16v5m0 6v5"/>',coach:'<circle cx="10" cy="7" r="3"/><path d="M3 21v-2a7 7 0 0 1 7-7c2.5 0 4.6 1.3 5.8 3.3M16 7l4 2-4 2zM20 9h2M16 11l-1 2"/>'};return `<span class="quick-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[type]}</svg></span>`;}
function courtDistance(courtId){const court=state.catalog.courts.find(c=>c.id===courtId),a=state.location;if(!a||court?.latitude==null||court?.longitude==null)return null;const rad=Math.PI/180,dl=(court.latitude-a.latitude)*rad,doLon=(court.longitude-a.longitude)*rad,q=Math.sin(dl/2)**2+Math.cos(a.latitude*rad)*Math.cos(court.latitude*rad)*Math.sin(doLon/2)**2;return 12742*Math.asin(Math.sqrt(q));}
function distanceBadge(courtId){const km=courtDistance(courtId);if(km===null)return '';return `<span class="distance-badge" title="Расстояние по прямой">⌖ ${km<5?'Рядом':km<10?'Близко':'Далеко'} · ${km<10?km.toFixed(1):Math.round(km)} км</span>`;}
function requestLocation(){const set=point=>{const latitude=Number(point?.latitude),longitude=Number(point?.longitude);if(!Number.isFinite(latitude)||!Number.isFinite(longitude)||Math.abs(latitude)>90||Math.abs(longitude)>180){toast('Не удалось определить местоположение');return;}state.location={latitude,longitude};state.geoPolls=0;render();toast('Расстояние до кортов рассчитано по прямой');};const manager=tg?.LocationManager;if(manager?.init&&manager?.getLocation){const get=()=>manager.getLocation(point=>point?set(point):toast('Разрешите геолокацию в настройках Telegram'));if(manager.isInited)get();else manager.init(get);}else if(navigator.geolocation)navigator.geolocation.getCurrentPosition(p=>set(p.coords),()=>toast('Разрешите доступ к геолокации'),{enableHighAccuracy:false,timeout:12000,maximumAge:300000});else toast('Геолокация недоступна на этом устройстве');}
function weatherBadge(startsAt,city='Краснодар'){if(city!==state.weatherCity)return `<span class="weather-missing">Прогноз для ${esc(city)} позже</span>`;const target=Date.parse(startsAt);if(!Number.isFinite(target)||target<Date.now()-3600000)return '';const hour=state.weather.find(x=>Math.abs(Date.parse(x.time)-target)<=30*60000);if(!hour||!Number.isFinite(hour.temperature))return `<span class="weather-missing" title="${state.weatherStatus==='unavailable'?'Погодный сервис недоступен':'Прогноз для этой даты ещё не опубликован'}">${state.weatherStatus==='unavailable'?'Погода недоступна':'Прогноз позже'}</span>`;const code=Number(hour.code),icon=code<=1?'☀️':code<=3||code===45||code===48?'☁️':'🌧️',label=code<=1?'Ясно':code<=3||code===45||code===48?'Пасмурно':'Осадки';return `<span class="weather-badge" title="Прогноз: ${label} · Open-Meteo" aria-label="${label}, ${Math.round(hour.temperature)} °C">${icon} ${Math.round(hour.temperature)}°</span>`;}
function gameOrganizer(g){return g.creatorName||g.members.find(m=>m.id===g.creatorId)?.name||'Организатор';}
function organizerLink(id,name,prefix='Организатор'){return `<button class="organizer-link" type="button" data-user="${esc(id)}" aria-label="Открыть профиль: ${esc(name)}">${prefix==='Тренер'?'Тренер - ':'Организатор: '}${esc(name)} →</button>`;}
function gameMessageButton(g){return g.creatorId===state.me?.id?'':`<button class="small-btn outline" data-direct="${esc(g.creatorId)}" data-name="${esc(gameOrganizer(g))}">Написать</button>`;}
function gameCard(g){const places=g.seats-g.members.length;return `<article class="card listing-card game-list-card clickable-game" data-game="${esc(g.id)}" role="button" tabindex="0" aria-label="Открыть игру: ${esc(g.venue)}"><div class="listing-head"><span class="listing-kicker">СПАРРИНГ${g.seats>2?' / ПАРНАЯ':''} · ${g.sport==='tennis'?'ТЕННИС':'ПАДЕЛ'}</span><span class="listing-date">${g.cancelled?'ОТМЕНЕНА · ':''}${day(g.startsAt)} · ${hour(g.startsAt)} ${weatherBadge(g.startsAt,g.city)}</span></div><h3 class="game-title">${esc(g.venue)}</h3>${organizerLink(g.creatorId,gameOrganizer(g))}<p class="listing-address">${esc(g.courtAddress||g.city)} · ${g.duration} мин</p>${distanceBadge(g.courtId)}<div class="listing-meta"><span>NTRP ${g.levelMin}–${g.levelMax}</span><span class="listing-places">${g.requestStatus==='pending'?'Ждёт подтверждения':places?`Свободно мест: ${places}`:'Мест нет'}</span><strong>${g.price} ₽/чел.</strong></div><div class="listing-bottom">${participantStrip(g.members)}<span class="listing-actions">${gameMessageButton(g)}<button class="small-btn outline" data-game="${g.id}">${g.joined?'Моя игра →':'Подробнее →'}</button></span></div></article>`;}
function filters(){return `<div class="filters" aria-label="Вид спорта">${[['all','Все игры'],['tennis','🎾 Теннис'],['padel',`${padelIcon()} Падел`]].map(([v,l])=>`<button class="chip ${state.filter===v?'active':''}" data-filter="${v}" aria-pressed="${state.filter===v}">${l}</button>`).join('')}</div>`;}
function visibleGames({mine=false,advanced=false,ignoreSport=false}={}){const today=dayKey(Date.now()),next=dayKey(Date.now()+86400000),weekEnd=Date.now()+7*86400000;return state.games.filter(g=>{const time=Date.parse(g.startsAt),places=g.seats-g.members.length;if(g.cancelled||state.cityFilter!=='all'&&g.city!==state.cityFilter||!mine&&time<=Date.now()||mine&&!g.joined||!ignoreSport&&state.filter!=='all'&&g.sport!==state.filter)return false;if(!advanced)return true;if(state.availableOnly&&places<=0||state.courts.length>0&&!state.courts.includes(g.courtId)||state.genderFilter!=='all'&&g.opponentGender!=='any'&&g.opponentGender!==state.genderFilter||state.ratingOnly&&g.kind!=='rating'||state.myLevelOnly&&(g.creatorRole!=='player'||g.creatorNtrp==null||state.me?.ntrpLevel==null||Math.abs(Number(g.creatorNtrp)-Number(state.me.ntrpLevel))>1)||!g.joined&&g.opponentGender!=='any'&&g.opponentGender!==state.me?.gender)return false;return state.when==='all'||state.when==='today'&&dayKey(time)===today||state.when==='tomorrow'&&dayKey(time)===next||state.when==='week'&&time<=weekEnd;}).sort((a,b)=>Date.parse(a.startsAt)-Date.parse(b.startsAt));}
function gamesList(mine=false,limit=0,advanced=false){const games=visibleGames({mine,advanced});return games.length?games.slice(0,limit||games.length).map(gameCard).join(''):`<div class="card empty"><div class="icon">🎾</div><strong>${mine?'Пока нет ваших игр':'Пока нет подходящих игр'}</strong><div class="muted">${advanced?'Попробуйте изменить фильтры или создайте свою игру':'Создайте игру и пригласите первого партнёра'}</div>${advanced?'<button class="small-btn outline" data-reset-filters style="margin-top:12px">Сбросить фильтры</button>':'<button class="small-btn" data-page="create" style="margin-top:12px">Создать игру</button>'}</div>`;}
function compactGameCard(g){const places=g.seats-g.members.length;return `<article class="card compact-card compact-game" data-game="${g.id}" role="button" tabindex="0" aria-label="Открыть игру: ${esc(g.venue)}"><span class="compact-line"><span class="compact-kicker">СПАРРИНГ${g.seats>2?' / ПАРНАЯ':''}</span><span class="compact-date">${day(g.startsAt)} · ${hour(g.startsAt)} ${weatherBadge(g.startsAt,g.city)}</span></span><strong class="compact-title">${g.sport==='tennis'?'Теннис':`${padelIcon()} Падел`} · ${esc(g.venue)}</strong>${organizerLink(g.creatorId,gameOrganizer(g))}${distanceBadge(g.courtId)}<span class="compact-footer"><span>NTRP ${g.levelMin}–${g.levelMax}</span><span class="compact-places">${participantStrip(g.members)}${places} ${places===1?'место':places<5?'места':'мест'}</span><span class="compact-price">${g.price} ₽/чел.</span></span></article>`;}
function compactTrainingCard(t){const places=t.seats-t.members.length;return `<article class="card compact-card compact-training" data-training="${t.id}" role="button" tabindex="0" aria-label="Открыть тренировку: ${esc(t.coachName)}"><span class="avatar">${avatar({name:t.coachName,photoData:t.coachPhotoData,avatarId:t.coachAvatarId})}</span><span class="compact-main"><span class="compact-line"><span class="compact-kicker">ТРЕНИРОВКА / ${t.sport==='padel'?'ПАДЕЛ':'ТЕННИС'}</span><span class="compact-date">${day(t.startsAt)} · ${hour(t.startsAt)} ${weatherBadge(t.startsAt,t.city)}</span></span><span class="compact-trainer">${organizerLink(t.coachId,t.coachName,'Тренер')}</span><span class="compact-format">${trainingFormat[t.format]||'Тренировка'} · стаж ${t.coachYears==null?'не указан':`${t.coachYears} лет`}</span><span class="compact-footer"><span class="compact-places">${participantStrip(t.members)}${places} ${places===1?'место':places<5?'места':'мест'} свободно</span><span class="compact-price">${t.price} ₽/чел.</span></span></span></article>`;}
function recommendedEvents(){
 const user=state.me;if(!user)return [];
 const city=user.city||'Краснодар',level=Number(user.ntrpLevel),hasLevel=user.ntrpLevel!=null;
 const games=state.games.filter(g=>g.sport==='tennis'&&g.requestStatus!=='pending'&&!g.cancelled&&!g.joined&&g.city===city&&Date.parse(g.startsAt)>Date.now()&&g.seats>g.members.length&&(g.opponentGender==='any'||g.opponentGender===user.gender)&&hasLevel&&level>=Number(g.levelMin)&&level<=Number(g.levelMax)&&(g.creatorNtrp==null||Math.abs(level-Number(g.creatorNtrp))<=1)).map(item=>({kind:'game',item}));
 const trainings=state.trainings.filter(t=>t.sport==='tennis'&&!t.cancelled&&!t.joined&&t.requestStatus!=='pending'&&t.coachId!==user.id&&(t.city||state.catalog.courts.find(c=>c.id===t.courtId)?.city||'Краснодар')===city&&Date.parse(t.startsAt)>Date.now()&&t.seats>t.members.length&&(t.ntrpMin==null||hasLevel&&level>=Number(t.ntrpMin)&&level<=Number(t.ntrpMax))).map(item=>({kind:'training',item}));
 return [...games,...trainings].sort((a,b)=>Date.parse(a.item.startsAt)-Date.parse(b.item.startsAt));
}
function nextEvent(){const id=state.me?.id;if(!id)return null;const events=[...state.games.filter(g=>!g.cancelled&&g.joined&&Date.parse(g.startsAt)>Date.now()).map(item=>({kind:'game',item})),...state.trainings.filter(t=>!t.cancelled&&(t.joined||t.coachId===id)&&Date.parse(t.startsAt)>Date.now()).map(item=>({kind:'training',item}))];return events.sort((a,b)=>Date.parse(a.item.startsAt)-Date.parse(b.item.startsAt))[0]||null;}
function matchesWord(n){return n%10===1&&n%100!==11?'матч':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'матча':'матчей';}
function progressData(){
 const data=state.progress||{months:[],totalGames:0,totalTrainings:0},rating=state.me?.ratings?.tennis;
 const example=/^(роман|roman)(\s|$)/i.test(state.me?.name||'')&&data.totalTrainings===0&&!(rating?.matches);
 if(!example)return {...data,example:false};
 const today=new Date(),months=Array.from({length:5},(_,i)=>{const date=new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth()-4+i,1));return {label:new Intl.DateTimeFormat('ru-RU',{month:'short',timeZone:'UTC'}).format(date),games:[3,5,6,7,9][i],trainings:[2,3,4,5,6][i],rating:[1500,1514,1526,1544,1568][i]};});
 return {months,totalGames:30,totalTrainings:20,example:true};
}
function progressChart(months){
 if(!months?.length)return '';
 const maxCount=Math.max(4,Math.ceil(Math.max(...months.map(m=>Math.max(m.games,m.trainings)))/2)*2),scores=months.map(m=>Number(m.rating)||1500),minimum=Math.floor((Math.min(...scores)-20)/20)*20,maximum=Math.ceil((Math.max(...scores)+20)/20)*20;
 const left=43,right=278,top=22,bottom=154,step=(right-left)/(months.length-1||1),yRating=v=>bottom-(v-minimum)/(maximum-minimum)*(bottom-top);
 const grid=[0,.5,1].map(f=>{const y=bottom-f*(bottom-top);return `<line x1="43" x2="278" y1="${y}" y2="${y}" stroke="#e2ebe0"/><text x="35" y="${y+4}" text-anchor="end">${Math.round(maxCount*f)}</text>`;}).join('');
 const bars=months.map((m,i)=>{const x=left+i*step,gameHeight=m.games/maxCount*(bottom-top),trainingHeight=m.trainings/maxCount*(bottom-top);return `<rect class="progress-game-bar" x="${x-15}" y="${bottom-gameHeight}" width="12" height="${gameHeight}" rx="4"><title>${esc(m.label)}: игр ${m.games}</title></rect><rect class="progress-training-bar" x="${x+3}" y="${bottom-trainingHeight}" width="12" height="${trainingHeight}" rx="4"><title>${esc(m.label)}: тренировок ${m.trainings}</title></rect><text x="${x}" y="177" text-anchor="middle">${esc(m.label)}</text>`;}).join('');
 const points=months.map((m,i)=>`${left+i*step},${yRating(scores[i]).toFixed(1)}`).join(' '),dots=months.map((m,i)=>`<circle class="progress-rating-dot" cx="${left+i*step}" cy="${yRating(scores[i]).toFixed(1)}" r="4"><title>${esc(m.label)}: рейтинг ${scores[i]}</title></circle>`).join('');
 return `<svg class="progress-chart" viewBox="0 0 320 189" role="img" aria-label="Игры и тренировки по месяцам, линия рейтинга Tennis GO"><g class="progress-axis">${grid}<text x="286" y="26">${maximum}</text><text x="286" y="158">${minimum}</text>${bars}</g><polyline points="${points}" fill="none" stroke="white" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${points}" fill="none" stroke="#244b39" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${dots}</svg>`;
}
function homeRating({profile=false}={}){
 const u=state.me,completedTrainings=state.trainings.filter(t=>t.completed&&(u.role==='coach'?t.coachId===u.id:t.joined)).length;
 if(u.role==='coach'){
  const upcoming=state.trainings.filter(t=>t.coachId===u.id&&!t.cancelled&&Date.parse(t.startsAt)>Date.now()).length;
  return `<section class="home-rating card"><div class="rating-heading"><div><span class="eyebrow">ВАША РАБОТА НА КОРТЕ</span><h2>Профиль тренера</h2></div><button class="text-btn" data-tab="profile">Подробнее →</button></div><div class="coach-rating-feature"><strong>${u.coachYears??'—'}</strong><span>лет тренерского стажа</span></div><div class="rating-stats coach-stats"><div><strong>${completedTrainings}</strong><span>тренировок проведено</span></div><div><strong>${upcoming}</strong><span>предстоит</span></div></div></section>`;
 }
 const data=progressData(),rating=u.ratings?.tennis||{rating:1500,matches:0},score=data.example?1568:Math.round(rating.rating),delta=data.example?68:data.ratingDelta;
 return `<section class="home-rating progress-card card"><div class="rating-heading"><div><span class="eyebrow">МОЙ ПРОГРЕСС</span><h2>Активность и рейтинг</h2></div>${profile?'':`<button class="text-btn" data-tab="profile">Подробнее →</button>`}</div><div class="progress-summary"><div class="progress-score"><small>Рейтинг Tennis GO</small><strong>${score}</strong><span class="progress-delta">${delta==null?'Рейтинг ещё не менялся':`${delta>0?'+':''}${delta} за период`}</span></div><div class="progress-ntrp">NTRP ${u.ntrpLevel==null?'—':Number(u.ntrpLevel).toFixed(1)}<small>самооценка</small></div></div><div class="progress-totals"><div><strong>${data.totalGames}</strong><span>игр</span></div><div><strong>${data.totalTrainings}</strong><span>тренировок</span></div></div><div class="progress-graph"><div class="progress-graph-head"><strong>Активность и рейтинг</strong>${data.example?'<span class="progress-demo-tag">Пример</span>':'<span>Последние 5 месяцев</span>'}</div><div class="progress-legend"><span><i class="progress-legend-games"></i>Игры</span><span><i class="progress-legend-trainings"></i>Тренировки</span><span><i class="progress-legend-rating"></i>Рейтинг</span></div>${progressChart(data.months)}</div><p class="progress-note">${data.example?'Пример оформления для вашего профиля. Реальные результаты будут появляться после игр и подтверждённых тренировок.':'Тренировки учитываются в активности, но не меняют рейтинг. Игры показаны по прошедшему расписанию.'}</p></section>`;
}
function home(){const event=nextEvent(),recommended=recommendedEvents().slice(0,3),u=state.me;return `<div class="content home-content"><div class="home-welcome"><span class="eyebrow">ВАШ ДЕНЬ НА КОРТЕ</span><h1>Привет, ${esc(u.name?.split(' ')[0]||'игрок')}!</h1><p class="lead">Планы и события рядом с вами · ${esc(u.city||'Краснодар')}.</p></div>${event?`<button class="home-plan has-art" data-${event.kind}="${event.item.id}"><span class="eyebrow">ВАШЕ БЛИЖАЙШЕЕ СОБЫТИЕ</span><strong>${event.kind==='game'?'Спарринг':'Тренировка'} · ${day(event.item.startsAt)} в ${hour(event.item.startsAt)}</strong><span>${esc(event.kind==='game'?event.item.venue:event.item.courtName)} · ${event.kind==='game'?event.item.sport==='tennis'?'Теннис':'Падел':esc(event.item.coachName)}</span><b>Подробнее о встрече →</b><img class="home-plan-art ${event.kind==='training'?'training-art':event.item.seats===4?'doubles-art':''}" src="${event.kind==='training'?'/assets/training-cat-pullup.png':event.item.seats===4?'/assets/doubles-squirrels-penguins.png':'/assets/sparring-rhino-bunny-court-white-pink.png'}" alt="" aria-hidden="true"></button>`:''}<div class="quick"><button class="secondary" data-page="news">${quickIcon("news")}Новости</button><button class="secondary" data-tab="community">${quickIcon("community")}Сообщество</button><button class="secondary" data-page="courts">${quickIcon("court")}Клубы и корты</button><button class="secondary" data-page="coaches">${quickIcon("coach")}Тренера</button></div>${eventsCarousel()}<section class="home-section"><div class="section-head"><h2>Подойдут вам</h2><button class="text-btn" data-tab="play">Найти всё →</button></div>${recommended.length?recommended.map(({kind,item})=>kind==='game'?compactGameCard(item):compactTrainingCard(item)).join(''):`<div class="card compact-empty">${u.ntrpLevel==null&&u.role==='player'?'Укажите NTRP в профиле, чтобы подобрать события.':'Сейчас нет теннисных событий в вашем городе, подходящих по уровню и свободным местам.'}</div>`}</section>${homeRating()}${contactFooter()}${state.config.demo?'<p class="footer-note">Демо режим · карточки и расписание для примера</p>':''}</div>`;}

function gameResults(){return `<div class="results-head"><strong>Игры</strong><span>${visibleGames({advanced:true}).length} найдено</span></div>${gamesList(false,0,true)}`;}
function gamesPage(){const cities=state.config.cities||[];const courts=state.catalog.courts.filter(c=>state.filter==='all'||c.sport===state.filter);return `<div class="content subpage"><div class="page-heading"><div><h1 class="page-title">Найти игру</h1><p class="lead">Игроки и корты рядом с вами.</p></div><button class="add-game" data-page="create" aria-label="Создать игру">＋</button></div>${filters()}<div class="search-panel"><button class="geo-locate" data-locate type="button">⌖ ${state.location?"Обновить моё местоположение":"Показать расстояние до кортов"}</button><p class="hint geo-explainer">${state.location?"Расстояние по прямой от вашего текущего местоположения.":"Разрешите геолокацию, чтобы увидеть: рядом до 5 км, близко до 10 км, далеко от 10 км."} <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">© OpenStreetMap</a></p><label class="field">Город<select id="game-city-filter"><option value="all">Все города</option>${cities.map(v=>`<option value="${esc(v)}" ${state.cityFilter===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><div class="date-filters" aria-label="Дата игры">${[['all','Любая дата'],['today','Сегодня'],['tomorrow','Завтра'],['week','7 дней']].map(([v,l])=>`<button class="date-chip ${state.when===v?'active':''}" data-when="${v}" aria-pressed="${state.when===v}">${l}</button>`).join('')}</div><div class="field"><span>Корты</span><details class="court-multiselect game-courts"><summary>Корты · ${state.courts.length?'выбрано '+state.courts.length:'все'}</summary><div class="court-checks">${courts.map(c=>`<label><input type="checkbox" data-game-court="${esc(c.id)}" ${state.courts.includes(c.id)?'checked':''}><span><strong>${esc(c.name)}</strong><small>${esc(c.address)}</small></span></label>`).join('')}</div></details></div><label class="field">Пол игроков<select id="gender-filter" aria-label="Пол игроков"><option value="all">Любой пол</option><option value="female" ${state.genderFilter==='female'?'selected':''}>Женщина</option><option value="male" ${state.genderFilter==='male'?'selected':''}>Мужчина</option></select></label><p class="hint" style="margin:-5px 0 9px">Показываем игры, доступные вам для участия.</p><button class="availability ${state.myLevelOnly?'active':''}" data-my-level aria-pressed="${state.myLevelOnly}" ${state.me?.ntrpLevel==null?'disabled':''}><span class="availability-dot"></span> Игроки моего уровня · ±1 NTRP</button><p class="hint" style="margin:0 0 9px">${state.me?.ntrpLevel==null?'Для фильтра укажите свой NTRP в профиле.':'Игры игроков с NTRP от '+Math.max(1,state.me.ntrpLevel-1).toFixed(1)+' до '+Math.min(7,state.me.ntrpLevel+1).toFixed(1)+'.'}</p><button class="availability ${state.ratingOnly?'active':''}" data-rating-only aria-pressed="${state.ratingOnly}"><span class="availability-dot"></span> Рейтинг</button><button class="availability ${state.availableOnly?'active':''}" data-available aria-pressed="${state.availableOnly}"><span class="availability-dot"></span> Только со свободными местами</button></div><div id="game-results">${gameResults()}</div><button class="button" data-page="create">＋ Создать игру</button><button class="button light" data-page="courts">Клубы и корты</button><button class="button light" data-page="court-booking">Забронировать корт</button>${contactFooter()}</div>`;}
const levelDescriptions={
 tennis:{'1.0':"Игрок только начинает играть в теннис.",'1.5':"Игрок имеет ограниченные навыки игры и еще работает над тем, чтобы держать мяч в игре.",'2.0':"Игрок нуждается в игровом опыте, имеет заметные недостатки при выполнении ударов, но уже знаком с основными положениями одиночных и парных игр.",'2.5':"Игрок учится предугадывать направление мяча, хотя чувство корта развито еще слабо. Может поддерживать игру в невысоком темпе с игроками подобного уровня.",'3.0':"Игрок стабильно отбивает мячи в среднем темпе, но чувствует неуверенность, когда пытается контролировать направление, глубину и силу при выполнении ударов.",'3.5':"Игрок достиг хорошего контроля направления при ударах средней сложности, но еще недостаточно контроля глубины и разнообразия. Решительно играет у сетки и работает над усовершенствованием парной игры.",'4.0':"Игрок выполняет надежные удары, контролирует направление и глубину с форхенда и бекхэнда плюс способен с успехом использовать свечи, смэши, выбивающие удары и удары с лета. Может допускать ошибки при подаче, использует командную тактику в парной игре.",'4.5':"Игрок приобрел навыки использования силы и подкрутки при ударах, начал управлять темпом игры, имеет хорошую работу ног, может контролировать глубину ударов и менять тактику игры в зависимости от противника. Игрок владеет сильной и точной первой, стабильной второй подачей, может атаковать у сетки.",'5.0':"Игрок хорошо чувствует мяч и часто выполняет особенные удары, вокруг которых строится игра. Может выигрывать очки или вынуждать соперника совершать ошибки с помощью укороченных мячей, \"убивать\" мячи с лета, успешно использовать свечи, укороченные удары, удары с полулета или смэши и использовать хорошую глубину и подкрутку на второй подаче.",'5.5':"Игрок в качестве главного оружия использует мощные удары и стабильность. Может менять стратегию и стиль игры в зависимости от ситуации и выполнять надежные удары в стрессовой ситуации.",'6.0':"Игрок не нуждается в рейтинге NTRP. Текущая или прошлая классификация говорит сама за себя. Игрок рейтинга 6.0 обычно соответствует уровню национальных соревнований среди юниоров и имеет национальный рейтинг. Игрок уровня 6.5 приближается к уровню 7.0 и имеет опыт участия в турнирах-сателлитах. Уровень 7.0 - игрок мирового класса, участвующий в турнирах международного уровня и для которого главным источником доходов являются призовые деньги.",'6.5':"Игрок не нуждается в рейтинге NTRP. Текущая или прошлая классификация говорит сама за себя. Игрок рейтинга 6.0 обычно соответствует уровню национальных соревнований среди юниоров и имеет национальный рейтинг. Игрок уровня 6.5 приближается к уровню 7.0 и имеет опыт участия в турнирах-сателлитах. Уровень 7.0 - игрок мирового класса, участвующий в турнирах международного уровня и для которого главным источником доходов являются призовые деньги.",'7.0':"Игрок не нуждается в рейтинге NTRP. Текущая или прошлая классификация говорит сама за себя. Игрок рейтинга 6.0 обычно соответствует уровню национальных соревнований среди юниоров и имеет национальный рейтинг. Игрок уровня 6.5 приближается к уровню 7.0 и имеет опыт участия в турнирах-сателлитах. Уровень 7.0 - игрок мирового класса, участвующий в турнирах международного уровня и для которого главным источником доходов являются призовые деньги."},
 padel:{'1.0':'Первый раз на корте','1.5':'Знакомлюсь с правилами и подачей','2.0':'Возвращаю простые мячи','2.5':'Держу короткий розыгрыш','3.0':'Уверенно играю с партнёром','3.5':'Использую стены и выходы к сетке','4.0':'Контролирую темп и положение команды','4.5':'Меняю тактику и умею защищаться','5.0':'Сильный турнирный любитель','5.5':'Регулярно играю турниры высокого уровня','6.0':'Профессиональный уровень','6.5':'Высокий профессиональный уровень','7.0':'Элита профессионального падела'}
};
function levelOptions(selected,sport='tennis'){return Object.keys(levelDescriptions[sport]).map(v=>`<option value="${v}" ${Number(v)===selected?'selected':''}>${v}</option>`).join('');}
function courtOptions(sport,selected){return state.catalog.courts.filter(c=>c.sport===sport).map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)} — ${esc(c.address)}</option>`).join('');}
function createPage(){return `<div class="content"><h1 class="page-title">Создать игру</h1><p class="lead">Выберите площадку и время, затем пригласите игроков.</p><form id="create-form"><div class="form-card"><h3>01 · Формат игры</h3><div class="seg"><label><input type="radio" name="sport" value="tennis" checked>🎾 Теннис</label><label><input type="radio" name="sport" value="padel">${padelIcon()} Падел</label></div><div class="row" style="margin-top:13px"><label class="field">Игроков<select name="seats"><option value="2">2 игрока</option><option value="4">4 игрока · парная</option></select></label><label class="approval-choice"><input type="checkbox" name="rating"> На рейтинг</label></div><label class="field" style="margin-top:12px">Кто может присоединиться<select name="opponentGender"><option value="any">Любой пол</option><option value="female">Только женщины</option><option value="male">Только мужчины</option></select></label><label class="approval-choice"><input type="checkbox" name="requiresApproval"> С подтверждением организатора</label><p class="hint">Выбранный пол проверяется при присоединении игроков. Рейтинг учитывается после подтверждения результата всеми участниками. NTRP в профиле остаётся вашей оценкой навыков.</p></div><div class="form-card"><h3>02 · Где и когда</h3><label class="field">Корт<select name="courtId" required>${courtOptions('tennis')}</select></label><div class="court-address" id="court-address">${esc(state.catalog.courts.find(c=>c.sport==='tennis')?.address||'')}</div><div class="row"><label class="field">Дата<input type="date" name="date" min="${tomorrow()}" value="${tomorrow()}" required></label><label class="field">Время<input type="time" name="time" value="19:00" required></label></div><div class="row"><label class="field">Продолжительность<select name="duration"><option>60</option><option selected>90</option><option>120</option></select></label><label class="field">₽ / человек<input type="number" name="price" value="1000" min="0" max="100000" required></label></div><p class="hint">Название и адрес подтверждены по данным клубов. Свободные слоты уточняются отдельно.</p></div><div class="form-card"><h3>03 · Подходящий уровень</h3><div class="row"><label class="field">От<select name="levelMin">${levelOptions(2.5)}</select></label><label class="field">До<select name="levelMax">${levelOptions(3.5)}</select></label></div><div class="level-explainer" id="level-summary">2.5 — ${esc(levelDescriptions.tennis['2.5'])}<br>3.5 — ${esc(levelDescriptions.tennis['3.5'])}</div><p class="hint" style="margin:0 0 9px">Ориентир для подбора игроков: теннис — по описаниям NTRP, падел — отдельная условная шкала.</p><details class="level-guide"><summary>Что означают уровни NTRP 1.0–7.0?</summary><div id="level-guide-items">${levelGuide('tennis')}</div></details><label class="field">Комментарий<textarea name="note" maxlength="240" placeholder="Темп игры или важные детали"></textarea></label></div><button class="button" type="submit">Создать игру →</button></form></div>`;}
function levelGuide(sport){return Object.entries(levelDescriptions[sport]).filter(([v])=>sport!=='tennis'||!['6.5','7.0'].includes(v)).map(([v,label])=>`<div><strong>${sport==='tennis'&&v==='6.0'?'6.0–7.0':v}</strong><span>${esc(label)}</span></div>`).join('');}
function updateCreateChoices(form){const sport=form.elements.sport.value,courts=state.catalog.courts.filter(c=>c.sport===sport),courtSelect=form.elements.courtId;
 courtSelect.innerHTML=courtOptions(sport);if(sport==='padel'&&form.elements.seats.value==='2')form.elements.seats.value='4';
 for(const name of ['levelMin','levelMax']){const select=form.elements[name],value=Number(select.value);select.innerHTML=levelOptions(value,sport);}
 form.querySelector('#level-guide-items').innerHTML=levelGuide(sport);syncGameFormat(form);updateCreateHints(form);
}
function syncGameFormat(form){const hint=form.querySelector('.form-card .hint');if(hint)hint.textContent='Рейтинговой может быть одиночная и парная игра. Счёт подтверждают все участники.';}
function updateCreateHints(form){const sport=form.elements.sport.value,court=state.catalog.courts.find(c=>c.id===form.elements.courtId.value),min=form.elements.levelMin.value,max=form.elements.levelMax.value;
 form.querySelector('#court-address').textContent=court?`📍 ${court.city||'Краснодар'}, ${court.address}`:'';
 form.querySelector('#level-summary').innerHTML=`${esc(min)} — ${esc(levelDescriptions[sport]?.[min]||'')}<br>${esc(max)} — ${esc(levelDescriptions[sport]?.[max]||'')}`;
}
function gameDetail(g){const places=g.seats-g.members.length;const canReport=!g.cancelled&&g.joined&&g.kind==='rating'&&g.members.length===g.seats&&g.attendanceConfirmed&&(g.seats===2||g.creatorId===state.me?.id)&&Date.parse(g.startsAt)+g.duration*60000<Date.now();const canAttend=!g.cancelled&&g.joined&&g.kind==='rating'&&g.members.length===g.seats&&Date.parse(g.startsAt)<Date.now();return `<div class="content subpage"><div class="detail-cover"><div><span class="eyebrow">СПАРРИНГ · ${g.seats>2?'ПАРНАЯ · ':''}${g.sport==='tennis'?'ТЕННИС':'ПАДЕЛ'} · ${g.kind==='rating'?'НА РЕЙТИНГ':'ОБЫЧНАЯ ИГРА'}${g.requiresApproval?' · С ПОДТВЕРЖДЕНИЕМ':''}</span><h1>${esc(g.venue)}</h1></div>${g.seats===4?'<img class="detail-art doubles-art" src="/assets/doubles-squirrels-penguins.png" alt="Две команды в парной игре">':''}</div>${g.courtAddress?`<div class="notice">📍 ${esc(g.city)}, ${esc(g.courtAddress)} ${distanceBadge(g.courtId)}</div>`:''}<div class="form-card detail-organizer"><span class="avatar">${avatar({name:gameOrganizer(g),photoData:g.creatorPhotoData,avatarId:g.creatorAvatarId})}</span>${organizerLink(g.creatorId,gameOrganizer(g))}</div><div class="detail-grid"><div class="stat"><small>Дата и время · МСК</small><strong>${day(g.startsAt)} · ${hour(g.startsAt)}</strong></div><div class="stat"><small>Стоимость</small><strong>${g.price} ₽ / чел.</strong></div><div class="stat"><small>Уровень</small><strong>${g.levelMin}–${g.levelMax}</strong></div><div class="stat"><small>Длительность</small><strong>${g.duration} минут</strong></div><div class="stat"><small>Кого ищут</small><strong>${genderName(g.opponentGender)}</strong></div></div><div class="form-card"><h3>Участники · ${g.members.length}/${g.seats}</h3>${g.seats===4?`<p class="hint">Команда 1: организатор и третий записавшийся · команда 2: второй и четвёртый.</p><strong>Команда 1</strong>${participantRows(g.members.filter(m=>m.team==='A'))}<strong>Команда 2</strong>${participantRows(g.members.filter(m=>m.team==='B'))}`:participantRows(g.members)}${places?`<div class="muted" style="padding-top:8px">＋ Свободно мест: ${places}</div>`:''}</div>${g.creatorId===state.me?.id?requestPanel('game',g):''}${g.note?`<div class="notice">${esc(g.note)}</div>`:''}<div class="detail-actions">${!g.cancelled&&!g.joined&&g.requestStatus==='pending'?'<div class="notice pending-notice">Ждёт подтверждения от организатора.</div><button class="button light" data-action="leave">Отменить заявку</button>':!g.cancelled&&!g.joined&&places?`<button class="button" data-action="join">${g.requiresApproval?'Отправить заявку':'Присоединиться к игре'}</button>`:''}${!g.cancelled&&g.joined?'<button class="button light" data-action="share">↗ Пригласить игрока</button>':''}${!g.cancelled&&g.joined&&g.creatorId!==state.me?.id&&!g.result?'<button class="text-btn" data-action="leave">Покинуть игру</button>':''}</div>${listingControls('game',g)}${canAttend&&!g.attendanceConfirmed?`<div class="form-card"><h3>Состоялась ли игра?</h3>${g.absenceBy?`<p class="notice">Заявлена неявка: ${esc(g.absenceReason)}. ${g.absenceDisputed?'Заявление оспорено.':'Рейтинг не меняется.'}</p>${g.absenceBy!==state.me?.id&&!g.absenceDisputed?'<button class="button light" data-action="contest-absence">Оспорить неявку</button>':''}`:g.seats===4?(g.attendanceDone?`<p class="muted">Подтверждено ${g.attendanceCount||0} из 4. Ожидаем остальных.</p>`:'<button class="button light" data-action="attend">Да, мы играли</button>'):!g.attendanceBy?'<button class="button light" data-action="attend">Да, мы играли</button>':g.attendanceBy!==state.me?.id?'<button class="button" data-action="confirm-attendance">Подтвердить встречу</button>':'<p class="muted">Ожидаем подтверждения соперника.</p>'}${g.seats===2&&!g.absenceBy&&Date.parse(g.startsAt)+g.duration*60000<Date.now()?`<form id="absence-form"><label class="field">Соперник не пришёл<textarea name="reason" minlength="5" maxlength="240" required placeholder="Коротко опишите ситуацию"></textarea></label><button class="button light" type="submit">Сообщить о неявке</button></form>`:''}</div>`:''}${g.result?`<div class="form-card" style="margin-top:15px"><h3>Результат · ${esc(g.result)}</h3><div class="muted">Счёт указан от лица создателя · ${g.resultConfirmed?'✅ Подтверждён':g.seats===4?`Подтверждено ${g.resultConfirmationCount||0} из 3 участников`:'Ожидает подтверждения'}</div>${g.resultDisputed?`<p class="notice">Счёт оспорен: ${esc(g.resultDisputeReason)}. Отправивший счёт игрок может исправить его.</p>`:''}${!g.resultConfirmed&&!g.resultDisputed&&g.joined&&g.resultBy!==state.me?.id&&!g.resultAcknowledged?'<button class="button" data-action="confirm" style="margin-top:12px">Подтвердить счёт</button><form id="dispute-form"><label class="field">Ошибка в счёте<input name="reason" minlength="5" maxlength="240" required placeholder="Укажите правильный счёт"></label><button class="button light" type="submit">Оспорить</button></form>':''}</div>`:''}${canReport&&!g.resultConfirmed&&(!g.result||g.resultBy===state.me?.id)?`<form id="result-form" class="form-card" style="margin-top:14px"><h3>${g.result?'Исправить':'Записать'} результат</h3><label class="field">Счёт от лица создателя<input name="score" value="${esc(g.result||'')}" placeholder="6:4, 6:3" required></label><button class="button light" type="submit">Отправить на подтверждение</button></form>`:''}${g.kind==='rating'?'<p class="notice">Рейтинг Tennis GO изменится после взаимного подтверждения встречи и счёта. NTRP остаётся вашим выбранным уровнем.</p>':''}</div>`;}
const trainingFormat={individual:'Индивидуальная',split:'Сплит · 2 человека',group:'Группа'};
function trainingCard(t){const available=t.seats-t.members.length;return `<article class="card listing-card training-card"><div class="listing-head"><span class="listing-kicker">ТРЕНИРОВКА / ${t.sport==='padel'?'ПАДЕЛ':'ТЕННИС'}</span><span class="listing-date">${t.cancelled?'ОТМЕНЕНА · ':''}${day(t.startsAt)} · ${hour(t.startsAt)} ${weatherBadge(t.startsAt,t.city)}</span></div><div class="listing-trainer"><span class="avatar">${avatar({name:t.coachName,photoData:t.coachPhotoData,avatarId:t.coachAvatarId})}</span><div>${organizerLink(t.coachId,t.coachName,'Тренер')}<small>${trainingFormat[t.format]||'Тренировка'} · стаж ${t.coachYears==null?'не указан':`${t.coachYears} лет`}</small></div></div><p class="listing-address">${esc(t.courtName)} · ${esc(t.courtAddress)}</p><div class="listing-meta"><span>${t.ntrpMin==null?'Без NTRP':`NTRP ${Number(t.ntrpMin).toFixed(1)}–${Number(t.ntrpMax).toFixed(1)}`}</span><span class="listing-places">${t.requestStatus==='pending'?'Ждёт подтверждения':available?`Свободно мест: ${available}`:'Мест нет'}</span><strong>${t.price} ₽/чел.</strong></div><div class="listing-bottom">${participantStrip(t.members)}<span class="listing-actions">${t.coachId===state.me?.id?'':`<button class="small-btn outline" data-direct="${esc(t.coachId)}" data-name="${esc(t.coachName)}">Написать</button>`}<button class="small-btn outline" data-training="${t.id}">Подробнее →</button></span></div></article>`;}

function filteredTrainings(){return state.trainings.filter(t=>!t.cancelled&&(state.trainingCity==='all'||t.city===state.trainingCity)&&(state.trainingSport==='all'||t.sport===state.trainingSport)&&(state.trainingGender==='all'||t.coachGender===state.trainingGender)&&(!state.trainingCourts.length||state.trainingCourts.includes(t.courtId))&&(state.trainingFormat==='all'||t.format===state.trainingFormat));}
function trainingResults(){const list=filteredTrainings();return `<div class="results-head"><strong>На ближайшие даты</strong><span>${list.length} найдено</span></div>${list.length?list.map(trainingCard).join(''):'<div class="card empty"><strong>Тренировок по фильтрам нет</strong><div class="muted">Выберите другие корты или формат.</div></div>'}`;}
function trainingFilters(){const cities=[...new Set(state.trainings.map(t=>t.city))].sort();const chosen=state.trainingCourts.length;return `<div class="search-panel training-filters"><label class="field">Город<select id="training-city-filter"><option value="all">Все города</option>${cities.map(v=>`<option value="${esc(v)}" ${state.trainingCity===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="field">Вид спорта<select id="training-sport-filter"><option value="all">Теннис и падел</option><option value="tennis" ${state.trainingSport==='tennis'?'selected':''}>Теннис</option><option value="padel" ${state.trainingSport==='padel'?'selected':''}>Падел</option></select></label><div class="filter-row"><label class="field">Пол тренера<select id="training-gender-filter"><option value="all">Любой пол</option><option value="female" ${state.trainingGender==='female'?'selected':''}>Женщина</option><option value="male" ${state.trainingGender==='male'?'selected':''}>Мужчина</option></select></label><label class="field">Формат<select id="training-format-filter"><option value="all">Любой формат</option><option value="individual" ${state.trainingFormat==='individual'?'selected':''}>Индивидуальная</option><option value="split" ${state.trainingFormat==='split'?'selected':''}>Сплит</option><option value="group" ${state.trainingFormat==='group'?'selected':''}>Групповая</option></select></label></div><details class="court-multiselect"><summary>Корты · ${chosen?`выбрано ${chosen}`:'все'}</summary><div class="court-checks">${state.catalog.courts.map(c=>`<label><input type="checkbox" data-training-court="${esc(c.id)}" ${state.trainingCourts.includes(c.id)?'checked':''}><span><strong>${esc(c.name)}</strong><small>${c.sport==='padel'?'Падел':'Теннис'} · ${esc(c.address)}</small></span></label>`).join('')}</div></details></div>`;}
function training(){return `<div class="content subpage"><div class="page-heading"><div><h1 class="page-title">Тренировки</h1><p class="lead">Занятия, опубликованные тренерами.</p></div>${state.me?.role==='coach'||state.me?.isAdmin?'<button class="add-game" data-page="create-training" aria-label="Создать тренировку">＋</button>':''}</div>${trainingFilters()}<div id="training-results">${trainingResults()}</div>${contactFooter()}${state.me?.role==='coach'||state.me?.isAdmin?'<button class="button" data-page="create-training">＋ Создать тренировку</button>':''}</div>`;}
function trainingDetail(t){const available=t.seats-t.members.length,own=t.coachId===state.me?.id;return `<div class="content subpage"><div class="detail-cover"><div><span class="eyebrow">${t.sport==='padel'?'ПАДЕЛ':'ТЕННИС'} · ${trainingFormat[t.format]||'Тренировка'}</span><h1>${esc(t.courtName)}</h1></div><img class="detail-art training-art" src="/assets/training-cat-pullup.png" alt="Кот готовится к теннисной тренировке"></div><div class="form-card"><button class="participant-row coach-link" data-user="${esc(t.coachId)}"><span class="avatar">${avatar({name:t.coachName,photoData:t.coachPhotoData,avatarId:t.coachAvatarId})}</span><span><strong>Тренер - ${esc(t.coachName)}</strong><small>Тренерский стаж: ${t.coachYears==null?'не указан':`${t.coachYears} лет`}</small></span><span class="participant-next">Профиль →</span></button></div><div class="detail-grid"><div class="stat"><small>Дата и время · МСК</small><strong>${day(t.startsAt)} · ${hour(t.startsAt)}</strong></div><div class="stat"><small>Стоимость</small><strong>${t.price} ₽ / чел.</strong></div><div class="stat"><small>Формат</small><strong>${trainingFormat[t.format]||'Тренировка'}</strong></div><div class="stat"><small>Длительность</small><strong>${t.duration} минут</strong></div><div class="stat"><small>Уровень</small><strong>${t.ntrpMin==null?'Без ограничений':`NTRP ${t.ntrpMin}–${t.ntrpMax}`}</strong></div><div class="stat"><small>Свободные места</small><strong>${available} из ${t.seats}</strong></div></div><div class="notice">📍 ${esc(t.city||'Краснодар')}, ${esc(t.courtAddress)}</div>${t.note?`<div class="form-card"><strong>О тренировке</strong><p class="muted">${esc(t.note)}</p></div>`:''}<div class="form-card"><h3>Записались · ${t.members.length}/${t.seats}</h3>${participantRows(t.members)}</div>${own?requestPanel('training',t):''}${t.cancelled?'<p class="notice">Тренировка отменена тренером.</p>':own?'':t.requestStatus==='pending'?`<div class="notice pending-notice">Ждёт подтверждения от тренера.</div><button class="button light" data-training-action="leave" data-training-id="${t.id}">Отменить заявку</button>`:t.joined?Date.parse(t.startsAt)>Date.now()?`<button class="button light" data-training-action="leave" data-training-id="${t.id}">Отменить запись</button>`:'':available?`<button class="button" data-training-action="join" data-training-id="${t.id}">${t.requiresApproval?'Отправить заявку':'Записаться'}</button>`:'<p class="notice">Свободных мест нет.</p>'}${listingControls('training',t)}${own&&!t.cancelled&&!t.completed&&Date.parse(t.startsAt)+t.duration*60000<Date.now()?`<button class="button light" data-training-complete="${t.id}">Подтвердить проведённую тренировку</button>`:''}${!t.cancelled&&t.completed&&t.joined&&!own&&!t.reviewed?`<form id="review-form" class="form-card"><h3>Отзыв о тренере</h3><label class="field">Оценка<select name="score"><option value="5">5 ★</option><option value="4">4 ★</option><option value="3">3 ★</option><option value="2">2 ★</option><option value="1">1 ★</option></select></label><label class="field">Комментарий<textarea name="comment" minlength="10" maxlength="500" required></textarea></label><button class="button light" type="submit">Опубликовать отзыв</button></form>`:''}</div>`;}
function listingControls(kind,item){const own=(kind==='game'?item.creatorId:item.coachId)===state.me?.id||!!state.me?.isAdmin,id=item.id;return `<div class="owner-controls">${item.cancelled?'<p class="notice">Объявление отменено. Запись закрыта.</p>':''}${own?'':`<button class="button light" data-direct="${esc(kind==='game'?item.creatorId:item.coachId)}" data-name="${esc(kind==='game'?gameOrganizer(item):item.coachName)}">Написать организатору</button>`}${own&&!item.cancelled&&Date.parse(item.startsAt)>Date.now()&&!(kind==='game'&&item.result)?`<button class="small-btn outline" data-edit="${kind}:${id}">✎ Редактировать</button>${state.confirmCancel===kind+':'+id?`<p class="notice">Отменить объявление? Записавшиеся увидят отметку об отмене.</p><button class="small-btn cancel-listing" data-confirm-cancel="${kind}:${id}">Да, отменить</button><button class="small-btn outline" data-dismiss-cancel>Оставить</button>`:`<button class="small-btn cancel-listing" data-cancel="${kind}:${id}">Отменить объявление</button>`}`:''}</div>`;}
function contactDetails(u){return `<div class="card contact-card"><strong>Контакты</strong><div class="contact-links">${u.phone?`<a href="tel:${esc(u.phone.replace(/[^+\d]/g,''))}">☎ ${esc(u.phone)}</a>`:''}${u.telegramContact?`<a href="https://t.me/${esc(u.telegramContact)}" target="_blank" rel="noopener noreferrer">Telegram · @${esc(u.telegramContact)}</a>`:''}${!u.phone&&!u.telegramContact?'<span class="muted">Контакты не указаны.</span>':''}</div></div>`;}
function publicProfile(u){return `<div class="content subpage"><h1 class="page-title">Профиль участника</h1><div class="profile-banner"><span class="avatar">${avatar(u)}</span><div><h2>${esc(u.name)}</h2><p>${u.role==='coach'?'Тренер':'Игрок'} · ${esc(u.city||'Краснодар')} · ${u.gender==='female'?'женщина':u.gender==='male'?'мужчина':'пол не указан'}</p></div></div>${u.id===state.me?.id?'':`<button class="button light profile-message" data-direct="${esc(u.id)}" data-name="${esc(u.name)}">✉ Написать лично</button>`}<div class="card profile-info"><strong>О себе</strong><p class="muted">${esc(u.about||'Информация пока не добавлена.')}</p><div class="profile-facts">${u.role==='coach'?`<span>Игра: ${sportNames(u.coachSports)}</span>`:''}<span>Стаж игры: ${u.playingYears==null?'не указан':`${u.playingYears} лет`}</span>${u.role==='coach'?`<span>Тренерский стаж: ${u.coachYears==null?'не указан':`${u.coachYears} лет`}</span>`:`<span>NTRP: ${u.ntrpLevel==null?'не указан':Number(u.ntrpLevel).toFixed(1)}</span>`}</div></div>${u.role==='player'?ratingTiles(u):`<div class="card"><strong>Отзывы о тренере</strong>${u.reviews?.length?u.reviews.map(r=>`<p>★ ${r.score}/5 · ${esc(r.body)}</p>`).join(''):'<p class="muted">Пока нет отзывов.</p>'}</div>`}${contactDetails(u)}</div>`;}
function createTrainingPage(){const allowed=state.me?.coachSports?.length?state.me.coachSports:['tennis','padel'],first=allowed[0];return `<div class="content"><h1 class="page-title">Создать тренировку</h1><p class="lead">Опубликуйте формат, площадку, время и цену.</p><form id="training-form"><div class="form-card"><h3>Вид спорта и формат</h3><label class="field">Тренировка<select name="sport" required>${allowed.map(s=>`<option value="${s}">${s==='tennis'?'🎾 Теннис':'Падел'}</option>`).join('')}</select></label><label class="field">Тип тренировки<select name="format"><option value="individual">Индивидуальная · 1 человек</option><option value="split">Сплит · 2 человека</option><option value="group">Групповая · 3–6 человек</option></select></label><label class="field" id="group-seats" hidden>Количество игроков<select name="seats"><option value="3">3 человека</option><option value="4">4 человека</option><option value="5">5 человек</option><option value="6">6 человек</option></select></label><div class="row"><label class="field">NTRP от<select name="ntrpMin"><option value="">Без уровня</option>${Object.keys(levelDescriptions.tennis).map(v=>`<option value="${v}">${v}</option>`).join('')}</select></label><label class="field">NTRP до<select name="ntrpMax"><option value="">Без уровня</option>${Object.keys(levelDescriptions.tennis).map(v=>`<option value="${v}">${v}</option>`).join('')}</select></label></div><p class="hint">Оставьте оба поля пустыми, если уровень не важен.</p><label class="approval-choice"><input type="checkbox" name="requiresApproval"> С подтверждением тренера</label></div><div class="form-card"><h3>Где и когда</h3><label class="field">Корт<select name="courtId" required>${courtOptions(first)}</select></label><div class="row"><label class="field">Дата<input type="date" name="date" min="${tomorrow()}" value="${tomorrow()}" required></label><label class="field">Время<input type="time" name="time" value="18:00" required></label></div><div class="row"><label class="field">Длительность<select name="duration"><option value="60">60 мин</option><option value="90" selected>90 мин</option><option value="120">120 мин</option></select></label><label class="field">₽ с человека<input type="number" name="price" min="0" max="100000" step="1" required></label></div><label class="field">Описание<textarea name="note" maxlength="240" placeholder="Что будет на тренировке"></textarea></label></div><div class="notice">Публикация не бронирует корт и не принимает оплату. Согласуйте площадку отдельно.</div><button class="button" type="submit">Опубликовать тренировку</button></form></div>`;}
function profile(){const u=state.me,level=u.ntrpLevel;return `<div class="content subpage"><h1 class="page-title">Мой профиль</h1><div class="profile-banner"><span class="avatar">${avatar(u)}</span><div><h2>${esc(u.name)}</h2><p>${u.role==='coach'?'Тренер':'Игрок'} · ${esc(u.city||'Краснодар')} · ${u.gender==='female'?'женщина':u.gender==='male'?'мужчина':'пол не указан'}</p></div></div>${state.marathon?.earned?'<div class="notice">🎾 Цель игрового марафона достигнута · туба теннисных мячей</div>':''}<button class="button light profile-edit" data-page="edit-profile">✎ Редактировать профиль</button>${u.role==='coach'||u.isAdmin?'<button class="button" data-page="create-training">＋ Создать тренировку</button>':''}${u.role==='coach'?'':`<div class="rating-box profile-level"><span>🎾 Уровень тенниса · NTRP</span><strong>${level==null?'Не указан':Number(level).toFixed(1)}</strong><p class="muted">${level==null?'Выберите свой уровень по описанию навыков.':esc(levelDescriptions.tennis[Number(level).toFixed(1)])}</p></div>`}<div class="card"><strong>О себе</strong><p class="muted">${esc(u.about||'Расскажите немного о себе в настройках профиля.')}</p><div class="muted">${u.role==='coach'||u.isAdmin?`Игра: ${sportNames(u.coachSports)} · `:''}Стаж игры: ${u.playingYears==null?'не указан':`${u.playingYears} лет`}${u.role==='coach'||u.isAdmin?` · Тренерский стаж: ${u.coachYears??'не указан'} лет`:''}</div></div>${u.role==='player'?homeRating({profile:true})+ratingTiles(u)+(state.ratingHistory.length?`<div class="card rating-history"><strong>История рейтинга</strong>${state.ratingHistory.slice(0,5).map(e=>`<div>${day(e.createdAt)} · ${e.sport==='tennis'?'Теннис':'Падел'} · ${Math.round(e.previous)} → ${Math.round(e.current)}</div>`).join('')}</div>`:''):''}<p class="hint">Ваш ID Telegram: ${esc(u.id)}</p>${contactDetails(u)}${u.isAdmin?'<div class="admin-entry"><span class="admin-badge">АДМИНИСТРАТОР</span><p>Игры, тренировки, клубы и модерация в одном аккаунте.</p><button class="button" data-page="admin">Открыть панель управления</button><button class="button light" data-page="admin-preview">Посмотреть меню игрока, тренера и клуба</button></div>':''}<div class="section-head"><h2>Мои бронирования кортов</h2></div>${state.clubBookings.length?state.clubBookings.map(b=>`<div class="card club-booking"><strong>${esc(b.clubName)} · ${day(b.startsAt)} ${hour(b.startsAt)}</strong><span>${esc(b.city)}, ${esc(b.address)} · ${b.duration} минут</span><button class="small-btn outline" data-cancel-court-booking="${esc(b.id)}">Отменить бронь</button></div>`).join(''):'<div class="card empty">Нет бронирований</div>'}${u.role==='coach'||u.isAdmin?`<div class="section-head"><h2>Мои тренировки</h2></div>${state.trainings.filter(t=>t.coachId===u.id).map(trainingCard).join('')||'<div class="card empty"><strong>Пока нет тренировок</strong></div>'}`:`<p class="notice">NTRP — самооценка; рейтинг Tennis GO меняется после взаимного подтверждения матча. Уровень NTRP вы указываете сами. Подтверждение счёта игры не меняет его автоматически.</p><div class="section-head"><h2>Мои тренировки</h2></div>${state.trainings.filter(t=>t.joined||t.requestStatus==='pending').map(trainingCard).join('')||'<div class="card empty">Нет записей на тренировки</div>'}<div class="section-head"><h2>Мои игры</h2></div>${state.games.filter(g=>g.joined||g.requestStatus==='pending').length?state.games.filter(g=>g.joined||g.requestStatus==='pending').map(gameCard).join(''):'<div class="card empty"><strong>Ещё нет игр</strong></div>'}`}</div>`;}

function sportNames(sports){return (sports?.length?sports:['tennis','padel']).map(s=>s==='tennis'?'теннис':'падел').join(' и ');}
function avatarGallery(){return `<div class="avatar-groups">${['Мужские','Женские'].map(group=>`<div><span class="avatar-group-title">${group}</span><div class="avatar-grid">${avatarChoices.filter(x=>x[2]===group).map(([id,label])=>`<button type="button" class="avatar-choice ${state.avatarId===id&&!state.profilePhotoData?'selected':''}" data-avatar="${id}" aria-pressed="${state.avatarId===id&&!state.profilePhotoData}">${tennisAvatar(id)}<span>${label}</span></button>`).join('')}</div></div>`).join('')}</div>`;}
function identityFields(u,registration=false){const isCoach=(registration?state.registrationRole:u.role)==='coach',level=u.ntrpLevel==null?'':Number(u.ntrpLevel).toFixed(1);return `<div class="form-card"><h3>Личные данные</h3><label class="field">Имя<input name="name" value="${esc(u.name||'')}" maxlength="60" required></label>${registration?`<div class="notice">Вы выбрали: ${state.registrationRole==='coach'?'тренер':'игрок'} <button type="button" class="text-btn" data-register-back>Изменить</button></div><input type="hidden" name="role" value="${state.registrationRole}">`:`<label class="field">Я<select name="role"><option value="player" ${u.role!=='coach'?'selected':''}>Игрок</option><option value="coach" ${u.role==='coach'?'selected':''}>Тренер</option></select></label>`}<div class="row"><label class="field">Пол<select name="gender" required><option value="">Выберите</option><option value="male" ${u.gender==='male'?'selected':''}>Мужчина</option><option value="female" ${u.gender==='female'?'selected':''}>Женщина</option></select></label><label class="field">Стаж игры, лет<input type="number" name="playingYears" min="0" max="80" step="1" value="${u.playingYears??''}" required></label></div><label class="field">Город<select name="city" required>${(state.config.cities||['Краснодар']).map(city=>`<option value="${esc(city)}" ${city===(u.city||'Краснодар')?'selected':''}>${esc(city)}</option>`).join('')}</select></label><div class="row"><label class="field">Телефон · по желанию<input type="tel" name="phone" inputmode="tel" maxlength="30" placeholder="+7 999 123-45-67" value="${esc(u.phone||'')}"></label><label class="field">Telegram · по желанию<input name="telegramContact" autocapitalize="none" maxlength="40" placeholder="@username" value="${esc(u.telegramContact?'@'+u.telegramContact:'')}"></label></div><p class="hint">Указанные контакты будут видны другим пользователям в вашем профиле.</p><label class="field">Информация о себе<textarea name="about" maxlength="500" placeholder="${isCoach?'Расскажите о вашем тренерском опыте':'Как часто играете, что ищете в приложении'}">${esc(u.about||'')}</textarea></label></div><div class="form-card" id="profile-ntrp-card" ${isCoach?'hidden':''}><h3>Уровень тенниса · NTRP</h3><label class="field">Ваш уровень<select name="ntrpLevel" ${isCoach?'':'required'}><option value="">Выберите уровень</option><option value="unknown">Я не знаю свой уровень · поставить 1.0</option>${Object.keys(levelDescriptions.tennis).map(v=>`<option value="${v}" ${level===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="level-explainer" id="profile-level-description">${level?esc(levelDescriptions.tennis[level]):'Выберите уровень, чтобы прочитать описание навыков.'}</div><details class="level-guide"><summary>Описание всех уровней NTRP</summary><div>${levelGuide('tennis')}</div></details></div><div class="form-card" id="coach-sports-card" ${isCoach||(!registration&&u.isAdmin)?'':'hidden'}><h3>Игра ${registration?'<span class="required-star">*</span>':''}</h3><p class="hint">Какие тренировки вы проводите?</p><div class="seg coach-sports"><label><input type="checkbox" name="coachSports" value="tennis" ${(u.coachSports||['tennis','padel']).includes('tennis')?'checked':''}> 🎾 Теннис</label><label><input type="checkbox" name="coachSports" value="padel" ${(u.coachSports||['tennis','padel']).includes('padel')?'checked':''}> ${padelIcon()} Падел</label></div></div><div class="form-card"><h3>Фото или теннисная аватарка <span class="required-star">*</span></h3><div class="profile-photo"><span class="avatar" id="photo-preview">${avatar({name:u.name,photoData:state.profilePhotoData,avatarId:state.avatarId})}</span><div><strong>Как вас увидят другие</strong><p class="hint">Загрузите фото или выберите один из шести образов.</p></div></div><label class="field">Своя фотография<input type="file" id="profile-photo-input" accept="image/*"></label><button type="button" class="text-btn" data-remove-photo>Убрать фото</button>${avatarGallery()}</div>${!registration?`<div class="form-card" id="coach-years-card" ${u.role==='coach'||u.isAdmin?'':'hidden'}><h3>Для тренера</h3><label class="field">Тренерский стаж, лет<input type="number" name="coachYears" min="0" max="80" step="1" value="${u.coachYears??''}" ${u.role==='coach'?'required':''}></label></div>`:''}`;}
function profileEditor(){return `<div class="content"><h1 class="page-title">Редактировать профиль</h1><form id="profile-form">${identityFields(state.me)}<button class="button" type="submit">Сохранить профиль</button></form></div>`;}
const clubSurfaces={hard:'Хард',clay:'Грунт',grass:'Натуральная трава',artificial_grass:'Искусственная трава',carpet:'Ковёр',other:'Другое'};
function clubRegistrationPage(edit=false){const c=state.me?.club||{},cities=state.config.cities||['Краснодар'];return `<div class="content subpage"><h1 class="page-title">${edit?'Данные клуба':'Представитель клуба/корта'}</h1><p class="lead">После регистрации клуб появится в каталоге только после проверки администратором.</p>${edit?'':'<p class="required-guide"><b>*</b> Обязательное поле. Выберите хотя бы один вид спорта и добавьте фото.</p>'}<form id="${edit?'club-edit-form':'club-registration-form'}"><div class="form-card"><label class="field">Ваше имя<input name="name" value="${esc(state.me?.name||'')}" maxlength="60" required></label><label class="field">Название клуба / корта<input name="clubName" value="${esc(c.name||'')}" maxlength="100" required></label><label class="field">Город<select name="city" required>${cities.map(city=>`<option value="${esc(city)}" ${city===(c.city||state.me?.city||'Краснодар')?'selected':''}>${esc(city)}</option>`).join('')}</select></label><label class="field">Адрес<input name="clubAddress" value="${esc(c.address||'')}" maxlength="180" required></label><label class="field">Телефон для связи<input type="tel" name="clubPhone" value="${esc(c.phone||'')}" placeholder="+7 999 123-45-67" required></label><div class="field">Вид спорта <span class="required-star">*</span></div><div class="seg"><label><input type="checkbox" name="clubSports" value="tennis" ${(c.sports||['tennis']).includes('tennis')?'checked':''}> Теннис</label><label><input type="checkbox" name="clubSports" value="padel" ${(c.sports||[]).includes('padel')?'checked':''}> Падел</label></div></div><div class="form-card"><h3>Корт и расписание</h3><label class="field">Тип покрытия<select name="clubSurface" required><option value="">Выберите покрытие</option>${Object.entries(clubSurfaces).map(([value,label])=>`<option value="${value}" ${c.surface===value?'selected':''}>${label}</option>`).join('')}</select></label><div class="row"><label class="field">Открытие<input type="time" name="opensAt" value="${esc(c.opensAt||'08:00')}" required></label><label class="field">Закрытие<input type="time" name="closesAt" value="${esc(c.closesAt||'22:00')}" required></label></div><p class="hint">Ежедневные часы работы по московскому времени. Онлайн запись доступна только в эти часы.</p><label class="field">Стоимость, ₽/час<input type="number" name="hourlyPrice" min="0" max="100000" value="${c.hourlyPrice??''}" required></label></div><div class="form-card"><h3>Фото клуба или корта</h3><div class="club-photo-preview" id="club-photo-preview">${state.clubPhotoData?`<img src="${esc(state.clubPhotoData)}" alt="Фото клуба">`:'Добавьте фото клуба или корта'}</div><label class="field">Фото<input type="file" id="club-photo-input" accept="image/*" ${state.clubPhotoData?'':'required'}></label><p class="hint">Фото будет видно игрокам после подтверждения клуба.</p></div><button class="button" type="submit">${edit?'Отправить данные на проверку':'Зарегистрировать клуб'}</button></form></div>`;}
function clubPage(){const c=state.me.club,status=c?.status;return `<div class="content subpage"><h1 class="page-title">Календарь клуба</h1><div class="card">${c?.photoData?`<img class="club-dashboard-photo" src="${esc(c.photoData)}" alt="${esc(c.name)}">`:''}<strong>${esc(c?.name||'Клуб')}</strong><p class="muted">${esc(c?.city||'')} · ${esc(c?.address||'')} · ${esc(c?.phone||'')}</p><p class="muted">${clubSurfaces[c?.surface]||'Покрытие не указано'} · ${esc(c?.opensAt||'—')}–${esc(c?.closesAt||'—')} · ${c?.hourlyPrice??'—'} ₽/час</p><p class="notice">${status==='approved'?'Клуб подтверждён':status==='rejected'?'Заявка отклонена. Исправьте данные и отправьте снова.':'Заявка ожидает проверки администратором. До подтверждения записей нет.'}</p><button class="small-btn outline" data-page="edit-club">Изменить данные клуба</button></div><label class="field">Дата<input id="club-calendar-date" type="date" value="${esc(state.clubDate||dayKey(Date.now()))}"></label><div class="section-head"><h2>Записи · ${state.clubCalendar.length}</h2></div>${state.clubCalendar.length?state.clubCalendar.map(b=>`<div class="card club-booking"><strong>${hour(b.startsAt)} · ${b.duration} минут · ${b.sport==='padel'?'Падел':'Теннис'}</strong><span>Забронировал: ${esc(b.guestName)}</span>${b.guestPhone?`<small>Телефон: ${esc(b.guestPhone)}</small>`:''}</div>`).join(''):'<div class="card empty">На выбранную дату записей нет.</div>'}</div>`;}
function courtBookingPage(){const options=state.catalog.courts.filter(c=>c.clubId);return `<div class="content subpage"><h1 class="page-title">Забронировать корт</h1><p class="lead">Запись будет видна представителю подтверждённого клуба. Публикация игры или тренировки не бронирует корт.</p>${options.length?`<form id="court-booking-form"><div class="form-card"><label class="field">Клуб / корт<select name="courtId">${options.map(c=>`<option value="${esc(c.id)}" ${state.bookingCourtId===c.id?'selected':''}>${esc(c.name)} · ${esc(c.city)}, ${esc(c.address)} · ${c.sport==='padel'?'Падел':'Теннис'} · ${c.hourlyPrice??'—'} ₽/час</option>`).join('')}</select></label><div class="row"><label class="field">Дата<input type="date" name="date" min="${tomorrow()}" value="${tomorrow()}" required></label><label class="field">Время<input type="time" name="time" value="18:00" required></label></div><label class="field">Длительность<select name="duration"><option value="60">60 минут</option><option value="90">90 минут</option><option value="120">120 минут</option></select></label><p class="hint">Часы работы и стоимость показаны в каталоге кортов. Бронирование не означает оплату.</p></div><button class="button" type="submit">Забронировать</button></form>`:'<div class="card empty">Пока нет подтверждённых клубов для онлайн записи.</div>'}</div>`;}
function courtsPage(){const cities=state.config.cities||[],list=state.catalog.courts.filter(c=>(state.courtCity==='all'||c.city===state.courtCity)&&(state.courtSport==='all'||c.sport===state.courtSport));return `<div class="content subpage"><h1 class="page-title">Клубы и корты</h1><p class="lead">Подтверждённые клубы доступны для онлайн записи. У остальных площадок уточняйте свободное время напрямую.</p><div class="row"><label class="field">Город<select id="court-city-filter"><option value="all">Все города</option>${cities.map(city=>`<option value="${esc(city)}" ${state.courtCity===city?'selected':''}>${esc(city)}</option>`).join('')}</select></label><label class="field">Спорт<select id="court-sport-filter"><option value="all">Оба</option><option value="tennis" ${state.courtSport==='tennis'?'selected':''}>Теннис</option><option value="padel" ${state.courtSport==='padel'?'selected':''}>Падел</option></select></label></div>${list.length?list.map(c=>`<article class="card court-list-card"><img src="${esc(c.image||'/assets/court_generic.svg')}" alt="Корт ${esc(c.name)}" loading="lazy"><div class="court-list-body"><span class="eyebrow">${c.sport==='padel'?'ПАДЕЛ':'ТЕННИС'}</span><h3>${esc(c.name)}</h3><p>${esc(c.city||'Краснодар')}, ${esc(c.address)}</p><div class="court-list-facts"><span>Покрытие: ${esc(clubSurfaces[c.surface]||c.surface||'не указано')}</span>${c.opensAt?`<span>Ежедневно ${esc(c.opensAt)}–${esc(c.closesAt)} · МСК</span>`:''}${c.hourlyPrice!=null?`<strong>${c.hourlyPrice} ₽/час</strong>`:''}</div>${c.clubId?`<button class="small-btn" data-book-court="${esc(c.id)}">Забронировать →</button>`:'<span class="muted">Онлайн запись пока недоступна</span>'}</div></article>`).join(''):'<div class="card empty">В выбранном городе площадок пока нет.</div>'}</div>`;}
function adminClubsPage(){return `<div class="content subpage"><h1 class="page-title">Проверка клубов</h1>${state.adminClubs.length?state.adminClubs.map(c=>`<div class="card club-review">${c.photoData?`<img src="${esc(c.photoData)}" alt="Фото клуба ${esc(c.name)}">`:''}<strong>${esc(c.name)}</strong><p>${esc(c.city)}, ${esc(c.address)}</p><small>${esc(c.contactName)} · ${esc(c.phone)} · ${esc(c.sports.join(', '))}</small><p class="muted">${esc(clubSurfaces[c.surface]||'Покрытие не указано')} · ${esc(c.opensAt||'—')}–${esc(c.closesAt||'—')} · ${c.hourlyPrice??'—'} ₽/час</p><div class="request-actions"><button class="small-btn" data-club-decision="approve" data-club-id="${esc(c.ownerId)}">Подтвердить</button><button class="small-btn outline" data-club-decision="reject" data-club-id="${esc(c.ownerId)}">Отклонить</button></div></div>`).join(''):'<div class="card empty">Новых заявок нет.</div>'}</div>`;}
function adminStatsPage(){const s=state.adminStats;if(!s)return '<div class="card empty">Загружаем статистику…</div>';const recent=s.daily.slice(-14),max=Math.max(1,...recent.map(d=>Math.max(d.active,d.games+d.trainings+d.messages)));return `<div class="admin-stat-grid">${[['Пользователей',s.total],['Новых сегодня',s.newToday],['Новых за 7 дней',s.new7],['Новых за 30 дней',s.new30],['Активных сегодня',s.activeToday],['Активных за 7 дней',s.active7],['Активных за 30 дней',s.active30]].map(([label,value])=>`<div class="card admin-stat"><strong>${value}</strong><span>${label}</span></div>`).join('')}</div><div class="card admin-activity"><strong>Активность за 14 дней</strong><div class="admin-bars">${recent.map(d=>`<div class="admin-bar-day" title="${d.day}: ${d.active} активных, ${d.games} игр, ${d.trainings} тренировок, ${d.messages} сообщений"><div class="admin-bar-pair"><i style="height:${Math.max(2,d.active/max*100)}%"></i><b style="height:${Math.max(2,(d.games+d.trainings+d.messages)/max*100)}%"></b></div><small>${d.day.slice(8)}</small></div>`).join('')}</div><p class="hint">Зелёный — активные пользователи, серый — игры, тренировки и сообщения. Учёт ежедневной активности начался после этого обновления.</p></div><div class="card"><strong>Действия за 7 дней</strong><div class="admin-action-grid">${[['Игры',s.last7.games],['Тренировки',s.last7.trainings],['Записи',s.last7.joins],['Сообщения',s.last7.messages],['Брони кортов',s.last7.bookings],['Новости',s.last7.news]].map(([label,value])=>`<span>${label}<b>${value}</b></span>`).join('')}</div></div>`;}
function adminUsersPage(){return `<form id="admin-user-search" class="search-panel"><label class="field">Имя или Telegram ID<input name="q" value="${esc(state.adminQuery)}" placeholder="Поиск участника"></label><button class="button light" type="submit">Найти</button></form>${state.adminUsers.length?state.adminUsers.map(u=>`<div class="card admin-person"><div><strong>${esc(u.name)}</strong><small>${esc(u.id)} · ${u.role==='club'?'Клуб':u.role==='coach'?'Тренер':'Игрок'} · ${esc(u.city)}</small>${u.blockedAt?'<span class="admin-blocked">Заблокирован</span>':''}</div><div class="admin-row-actions"><button class="small-btn outline" data-user="${esc(u.id)}">Профиль</button>${u.id===state.me?.id?'<span class="muted">Ваш аккаунт</span>':u.blockedAt?`<button class="small-btn" data-admin-unblock="${esc(u.id)}">Разблокировать</button>`:`<button class="small-btn cancel-listing" data-admin-block="${esc(u.id)}">Блокировать</button>`}</div>${state.pendingBlock===u.id?`<form id="admin-block-form" data-user-id="${esc(u.id)}"><label class="field">Причина блокировки<textarea name="reason" minlength="5" maxlength="240" required placeholder="Укажите причину"></textarea></label><button class="small-btn cancel-listing" type="submit">Подтвердить блокировку</button><button class="small-btn outline" type="button" data-admin-dismiss>Отмена</button></form>`:''}</div>`).join(''):'<div class="card empty">Пользователи не найдены.</div>'}`;}
function adminMessagesPage(){return `<p class="lead">Последние 100 сообщений. Удалённое сообщение исчезнет у обоих собеседников.</p>${state.adminMessages.length?state.adminMessages.map(m=>`<div class="card admin-message"><small>${esc(m.senderName)} → ${esc(m.recipientName)} · ${m.kind==='direct'?'Личный чат':'Объявление'} · ${day(m.createdAt)} ${hour(m.createdAt)}</small><p>${esc(m.body)}</p>${state.confirmModeration===`message:${m.kind}:${m.id}`?`<div class="notice">Удалить это сообщение для всех?</div><button class="small-btn cancel-listing" data-admin-confirm="message:${m.kind}:${m.id}">Да, удалить</button><button class="small-btn outline" data-admin-dismiss>Отмена</button>`:`<button class="small-btn outline" data-admin-ask="message:${m.kind}:${m.id}">Удалить</button>`}</div>`).join(''):'<div class="card empty">Сообщений пока нет.</div>'}`;}
function adminListingsPage(kind){const list=state.adminListings[kind==='game'?'games':'trainings'];return `${list.length?list.map(x=>`<div class="card admin-listing"><strong>${esc(x.venue)} · ${day(x.startsAt)} ${hour(x.startsAt)}</strong><small>${kind==='game'?'Игра':'Тренировка'} · ${esc(x.ownerName)} · ${x.sport==='padel'?'Падел':'Теннис'}</small>${x.cancelledAt?'<span class="muted">Отменено</span>':state.confirmModeration===`${kind}:${x.id}`?`<div class="notice">Отменить событие? Записавшиеся получат уведомление.</div><button class="small-btn cancel-listing" data-admin-confirm="${kind}:${x.id}">Да, отменить</button><button class="small-btn outline" data-admin-dismiss>Оставить</button>`:`<button class="small-btn cancel-listing" data-admin-ask="${kind}:${x.id}">Отменить</button>`}</div>`).join(''):'<div class="card empty">Предстоящих объявлений нет.</div>'}`;}
function adminClubsContent(){return `${state.adminClubs.some(c=>c.ownerId===state.me?.id)?'':'<button class="button light" data-admin-club-create>＋ Добавить свой клуб</button>'}${state.adminClubs.length?state.adminClubs.map(c=>`<div class="card admin-club"><strong>${esc(c.name)}</strong><small>${esc(c.city)}, ${esc(c.address)} · ${esc(c.contactName)}</small><p class="muted">${c.status==='approved'?'Подтверждён':c.status==='pending'?'Ждёт проверки':'Отклонён'} · ${esc(clubSurfaces[c.surface]||'Покрытие не указано')} · ${c.hourlyPrice??'—'} ₽/час</p><div class="admin-row-actions">${c.status==='pending'?`<button class="small-btn" data-club-decision="approve" data-club-id="${esc(c.ownerId)}">Подтвердить</button><button class="small-btn outline" data-club-decision="reject" data-club-id="${esc(c.ownerId)}">Отклонить</button>`:''}<button class="small-btn outline" data-admin-calendar="${esc(c.ownerId)}">Календарь</button><button class="small-btn outline" data-admin-club-edit="${esc(c.ownerId)}">Изменить</button></div></div>`).join(''):'<div class="card empty">Клубов пока нет.</div>'}`;}
function adminRolePreviewPage(){const role=state.previewRole,oldMe=state.me,oldTab=state.tab,oldPlay=state.playView,oldCalendar=state.clubCalendar;let content;
  try{state.me={...oldMe,isAdmin:false,role,coachSports:role==='coach'?['tennis','padel']:[],coachYears:role==='coach'?(oldMe.coachYears??5):null,ntrpLevel:role==='player'?(oldMe.ntrpLevel??3):null,club:role==='club'?(oldMe.club||{name:'Пример клуба',address:'ул. Красная, 10',city:'Краснодар',phone:'+7 900 000-00-00',sports:['tennis'],status:'approved',surface:'clay',opensAt:'08:00',closesAt:'22:00',hourlyPrice:1200}):null};state.tab=state.previewTab;
    if(role==='club'){state.clubCalendar=[{startsAt:new Date().toISOString(),duration:60,sport:'tennis',guestName:'Пример игрока'}];content=clubPage();}
    else{if(state.previewTab==='play')state.playView=role==='coach'?'training':'games';content=state.previewTab==='play'?playPage():state.previewTab==='chat'?'<div class="content subpage"><h1 class="page-title">Чаты</h1><div class="card empty">Здесь будут диалоги участника.</div></div>':state.previewTab==='profile'?profile():home();}
  }finally{state.me=oldMe;state.tab=oldTab;state.playView=oldPlay;state.clubCalendar=oldCalendar;}
  const roles=[['player','Игрок'],['coach','Тренер'],['club','Клуб / корт']],tabs=role==='club'?[['home','Календарь']]:[['home','Главная'],['play','Играть'],['chat','Чат'],['profile','Профиль']];
  return `<div class="role-preview"><p class="lead">Посмотрите меню каждой роли. Это просмотр: ваши данные и права администратора не меняются.</p><div class="role-preview-switch">${roles.map(([id,label])=>`<button type="button" data-preview-role="${id}" class="${role===id?'active':''}">${label}</button>`).join('')}</div><div class="role-preview-screen"><div class="role-preview-caption">${roles.find(([id])=>id===role)?.[1]} · ${tabs.find(([id])=>id===state.previewTab)?.[1]||'Календарь'}</div><div class="role-preview-content">${content}</div><div class="role-preview-nav">${tabs.map(([id,label])=>`<button type="button" data-preview-tab="${id}" class="${state.previewTab===id?'active':''}">${label}</button>`).join('')}</div></div></div>`;}
function adminPage(){const tabs=[['overview','Обзор'],['users','Люди'],['messages','Сообщения'],['games','Игры'],['trainings','Тренировки'],['clubs','Клубы'],['preview','Роли']];const body=state.adminTab==='overview'?adminStatsPage():state.adminTab==='users'?adminUsersPage():state.adminTab==='messages'?adminMessagesPage():state.adminTab==='games'?adminListingsPage('game'):state.adminTab==='trainings'?adminListingsPage('training'):state.adminTab==='preview'?adminRolePreviewPage():adminClubsContent();return `<div class="content subpage"><div class="admin-title"><span class="admin-badge">АДМИНИСТРАТОР</span><h1 class="page-title">Управление Tennis GO</h1></div><div class="admin-tabs">${tabs.map(([key,label])=>`<button data-admin-tab="${key}" class="${state.adminTab===key?'active':''}">${label}</button>`).join('')}</div>${body}</div>`;}
function adminCalendarPage(){const c=state.adminClubs.find(x=>x.ownerId===state.adminClubId);return `<div class="content subpage"><h1 class="page-title">Календарь · ${esc(c?.name||'Клуб')}</h1><label class="field">Дата<input type="date" id="admin-calendar-date" value="${esc(state.clubDate||dayKey(Date.now()))}"></label><h2 class="admin-subhead">Записи: ${state.adminCalendar.length}</h2>${state.adminCalendar.length?state.adminCalendar.map(b=>`<div class="card club-booking"><strong>${hour(b.startsAt)} · ${b.duration} мин · ${b.sport==='padel'?'Падел':'Теннис'}</strong><span>${esc(b.guestName)}</span>${b.guestPhone?`<small>${esc(b.guestPhone)}</small>`:''}</div>`).join(''):'<div class="card empty">На этот день записей нет.</div>'}</div>`;}
function adminClubForm(){const c=state.adminClubs.find(x=>x.ownerId===state.adminClubId)||{},edit=!!state.adminClubId;return `<div class="content subpage"><h1 class="page-title">${edit?'Изменить клуб':'Добавить клуб'}</h1><form id="admin-club-form"><div class="form-card"><label class="field">Название<input name="clubName" value="${esc(c.name||'')}" maxlength="100" required></label><label class="field">Город<select name="city">${(state.config.cities||['Краснодар']).map(city=>selectedOption(city,c.city||state.me.city,city)).join('')}</select></label><label class="field">Адрес<input name="clubAddress" value="${esc(c.address||'')}" required></label><label class="field">Телефон<input name="clubPhone" type="tel" value="${esc(c.phone||'')}" required></label><div class="seg"><label><input type="checkbox" name="clubSports" value="tennis" ${(c.sports||['tennis']).includes('tennis')?'checked':''}> Теннис</label><label><input type="checkbox" name="clubSports" value="padel" ${(c.sports||[]).includes('padel')?'checked':''}> Падел</label></div></div><div class="form-card"><label class="field">Покрытие<select name="clubSurface" required>${Object.entries(clubSurfaces).map(([v,label])=>selectedOption(v,c.surface||'',label)).join('')}</select></label><div class="row"><label class="field">Открытие<input name="opensAt" type="time" value="${esc(c.opensAt||'08:00')}" required></label><label class="field">Закрытие<input name="closesAt" type="time" value="${esc(c.closesAt||'22:00')}" required></label></div><label class="field">Стоимость, ₽/час<input name="hourlyPrice" type="number" min="0" max="100000" value="${c.hourlyPrice??''}" required></label><div class="club-photo-preview" id="club-photo-preview">${state.clubPhotoData?`<img src="${esc(state.clubPhotoData)}" alt="Фото клуба">`:'Добавьте фото клуба'}</div><label class="field">Фото<input type="file" id="club-photo-input" accept="image/*" ${state.clubPhotoData?'':'required'}></label></div><button class="button" type="submit">${edit?'Сохранить':'Добавить подтверждённый клуб'}</button></form></div>`;}
function marathonCard(showTitle=true){const m=state.marathon;if(!m)return '';const percent=Math.min(100,Math.round(100*m.games/m.goal));return `<section class="marathon-section">${showTitle?`<div class="section-head"><h2>🔥 События Tennis GO</h2><button class="text-btn" data-page="event-marathon">Смотреть →</button></div>`:''}<div class="marathon-card"><div class="marathon-banner"><div class="marathon-banner-copy"><span class="eyebrow">ИГРОВОЙ МАРАФОН</span><h3>${esc(m.title)}</h3><p>Сыграйте 20 подтверждённых рейтинговых матчей за месяц</p><span class="marathon-prize">🎾 Приз: Туба теннисных мячей</span></div></div><div class="marathon-content"><div class="marathon-progress"><strong>Ваш результат: ${m.games} ${matchesWord(m.games)}</strong><div class="marathon-bar"><span style="width:${percent}%"></span></div><small>${m.games} / ${m.goal}${m.earned?' · цель достигнута':''}</small></div><div class="marathon-leaders"><strong>Лидеры</strong>${m.leaders.length?m.leaders.map((u,i)=>`<div><b>${i+1}</b><span>${esc(u.name)}</span><strong>${u.games}</strong></div>`).join(''):'<small>Пока нет подтверждённых игр</small>'}</div></div><div class="marathon-actions"><button class="button" data-event-action="play">Найти игру</button><button class="button light" data-page="event-marathon">Подробнее</button></div></div></section>`;}
function eventsCarousel(){const items=[...(state.marathon?[{kind:'marathon'}]:[]),...state.news.map(item=>({kind:'news',item}))];if(!items.length)return '';const index=((state.eventIndex%items.length)+items.length)%items.length,current=items[index],content=current.kind==='marathon'?marathonCard(false):`<article class="card event-news-slide"><div class="event-news-cover"><span>НОВОСТИ TENNIS GO</span></div><div class="event-news-body"><small>${day(current.item.publishedAt)} · ${hour(current.item.publishedAt)}</small><h3>${esc(current.item.title)}</h3><p>${esc(current.item.body.slice(0,170))}${current.item.body.length>170?'…':''}</p><button class="small-btn" data-page="news">Читать новости →</button></div></article>`;return `<section class="events-carousel" data-events-carousel tabindex="0" aria-label="События Tennis GO, листайте вправо или влево"><div class="section-head"><h2>🔥 События Tennis GO</h2><div class="events-arrows"><button type="button" data-event-step="-1" aria-label="Предыдущее событие">‹</button><button type="button" data-event-step="1" aria-label="Следующее событие">›</button></div></div><div class="events-slide" aria-live="polite">${content}</div><div class="events-dots">${items.map((_,i)=>`<button type="button" data-event-go="${i}" class="${index===i?'active':''}" aria-label="Событие ${i+1} из ${items.length}" aria-current="${index===i}"></button>`).join('')}</div><p class="events-swipe-hint">Листайте новости ← →</p></section>`;}
function moveEvent(step){const count=(state.marathon?1:0)+state.news.length;if(!count)return;state.eventIndex=(state.eventIndex+step+count)%count;render();}
function marathonPage(){const m=state.marathon;if(!m)return '<div class="content subpage">Событие загружается</div>';return `<div class="content subpage marathon-detail"><h1 class="page-title">${esc(m.title)}</h1>${marathonCard()}<div class="card"><strong>Как участвовать</strong><p class="muted">Создайте игру с галочкой «На рейтинг» или присоединитесь к такой игре. После матча все участники подтверждают встречу и счёт. Матч засчитывается в месяц его проведения, когда результат подтверждён.</p><p class="muted">Приз за ${m.goal} матчей — туба теннисных мячей. После достижения цели получение приза согласуется с организатором Tennis GO. Таблица лидеров считает подтверждённые матчи, сыгранные через приложение.</p></div></div>`;}
function registration(){if(state.registrationStep===1)return `<div class="content onboarding"><div class="step-count">Регистрация · шаг 1 из ${state.registrationRole==='coach'?3:2}</div><h1 class="page-title">Добро пожаловать в Tennis GO</h1><p class="lead">Выберите, как будете пользоваться приложением.</p><div class="role-grid"><button data-role="player" class="role-card"><span>🎾</span><strong>Я игрок</strong><small>Ищу игру, партнёра или тренировку</small></button><button data-role="coach" class="role-card"><span>◷</span><strong>Я тренер</strong><small>Провожу тренировки и играю</small></button><button data-role="club" class="role-card"><span>▦</span><strong>Представитель клуба/корта</strong><small>Календарь записей после проверки клуба</small></button></div></div>`;if(state.registrationRole==='club'&&state.registrationStep===2)return clubRegistrationPage();if(state.registrationStep===3)return `<div class="content onboarding"><div class="step-count">Регистрация · шаг 3 из 3</div><h1 class="page-title">Тренерский опыт</h1><p class="lead">Укажите, сколько лет вы проводите тренировки.</p><p class="required-guide"><b>*</b> Обязательное поле.</p><form id="coach-registration-form"><div class="form-card"><label class="field">Тренерский стаж, лет<input type="number" name="coachYears" min="0" max="80" step="1" value="${state.registrationDraft?.coachYears??''}" required></label></div><button class="button" type="submit">Завершить регистрацию</button></form></div>`;return `<div class="content onboarding"><div class="step-count">Регистрация · шаг 2 из ${state.registrationRole==='coach'?3:2}</div><h1 class="page-title">Расскажите о себе</h1><p class="lead">Эти данные помогут другим игрокам познакомиться с вами.</p><p class="required-guide"><b>*</b> Обязательное поле. Телефон, Telegram и «О себе» можно пропустить.</p><form id="registration-form">${identityFields(state.registrationDraft||state.me,true)}<button class="button" type="submit">${state.registrationRole==='coach'?'Далее →':'Завершить регистрацию'}</button></form></div>`;}
function identityPayload(form){const admin=!!state.me?.isAdmin;return {name:String(form.get('name')||'').trim(),role:form.get('role'),gender:form.get('gender'),playingYears:Number(form.get('playingYears')),ntrpLevel:form.get('role')==='coach'?null:form.get('ntrpLevel')==='unknown'?1:form.get('ntrpLevel')?Number(form.get('ntrpLevel')):null,about:form.get('about'),city:form.get('city'),phone:String(form.get('phone')||'').trim(),telegramContact:String(form.get('telegramContact')||'').trim().replace(/^@/,''),coachSports:form.get('role')==='coach'||admin?form.getAll('coachSports'):[],coachYears:form.get('role')==='coach'||admin?(form.get('coachYears')!==''&&form.has('coachYears')?Number(form.get('coachYears')):null):null,photoData:state.profilePhotoData,avatarId:state.avatarId};}
async function saveIdentity(payload){if(payload.role==='coach'&&!payload.coachSports.length)throw Error('Выберите теннис, падел или оба вида спорта');const data=await api('/profile','POST',payload);state.me=data.user;if(['edit-profile','edit-club'].includes(state.form))state.history.pop();state.form='';await refresh();if(state.pendingGame&&state.me.role!=='club'){try{state.detail=(await api(`/games/${state.pendingGame}`)).game;}catch{toast('Игра по ссылке не найдена');}state.pendingGame=null;}render();toast('Профиль сохранён');}
async function imageData(file,landscape=false){
 if(!file.type.startsWith('image/'))throw Error('Выберите файл изображения');
 if(file.size>10_000_000)throw Error('Фото должно быть меньше 10 МБ');
 const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Не удалось прочитать фото'));reader.readAsDataURL(file);});
 let img;try{img=await new Promise((resolve,reject)=>{const picture=new Image();picture.onload=()=>resolve(picture);picture.onerror=()=>reject(Error('Фото не распознано'));picture.src=source;});}
 catch{try{img=await createImageBitmap(file);}catch{throw Error('Не удалось открыть фото. Попробуйте JPG или PNG вместо HEIC.');}}
 const canvas=document.createElement('canvas');canvas.width=landscape?640:400;canvas.height=landscape?360:400;
 const ctx=canvas.getContext('2d');if(!ctx)throw Error('Не удалось обработать фото');
 const width=img.naturalWidth||img.width,height=img.naturalHeight||img.height;if(!width||!height)throw Error('Фото повреждено');const ratio=landscape?16/9:1,sourceWidth=Math.min(width,height*ratio),sourceHeight=sourceWidth/ratio;
 ctx.drawImage(img,(width-sourceWidth)/2,(height-sourceHeight)/2,sourceWidth,sourceHeight,0,0,canvas.width,canvas.height);
 img.close?.();
 let data=canvas.toDataURL('image/jpeg',.8);if(data.length>340000)data=canvas.toDataURL('image/jpeg',.6);
 if(!data.startsWith('data:image/jpeg;base64,')||data.length>340000)throw Error('Не удалось уменьшить фото, выберите JPG или PNG');
 return data;
}
function selectedOption(value,selected,label){return `<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`;}
function editGamePage(){const g=state.games.find(x=>x.id===state.editTarget?.id);if(!g)return '<div class="content">Игра не найдена</div>';return `<div class="content"><h1 class="page-title">Редактировать игру</h1><form id="edit-game-form" class="edit-listing"><div class="form-card"><label class="field">Вид спорта<select name="sport">${selectedOption('tennis',g.sport,'Теннис')}${selectedOption('padel',g.sport,'Падел')}</select></label><label class="field">Корт<select name="courtId" required>${courtOptions(g.sport,g.courtId)}</select></label><div class="row"><label class="field">Дата<input type="date" name="date" value="${dayKey(g.startsAt)}" required></label><label class="field">Время<input type="time" name="time" value="${hour(g.startsAt)}" required></label></div><div class="row"><label class="field">Игроков<select name="seats">${selectedOption(2,g.seats,'2 игрока')}${selectedOption(4,g.seats,'4 игрока · парная')}</select></label><label class="approval-choice"><input type="checkbox" name="rating" ${g.kind==='rating'?'checked':''}> На рейтинг</label></div><div class="row"><label class="field">Мин. уровень<select name="levelMin">${levelOptions(g.levelMin,g.sport)}</select></label><label class="field">Макс. уровень<select name="levelMax">${levelOptions(g.levelMax,g.sport)}</select></label></div><div class="row"><label class="field">Длительность<select name="duration">${[60,90,120].map(v=>selectedOption(v,g.duration,v+' мин')).join('')}</select></label><label class="field">₽ / чел.<input type="number" name="price" min="0" max="100000" value="${g.price}" required></label></div><label class="field">Кто может присоединиться<select name="opponentGender">${selectedOption('any',g.opponentGender,'Любой пол')}${selectedOption('female',g.opponentGender,'Женщины')}${selectedOption('male',g.opponentGender,'Мужчины')}</select></label><label class="approval-choice"><input type="checkbox" name="requiresApproval" ${g.requiresApproval?'checked':''}> С подтверждением организатора</label><label class="field">Комментарий<textarea name="note" maxlength="240">${esc(g.note||'')}</textarea></label></div><button class="button" type="submit">Сохранить изменения</button></form></div>`;}
function editTrainingPage(){const t=state.trainings.find(x=>x.id===state.editTarget?.id);if(!t)return '<div class="content">Тренировка не найдена</div>';const allowed=state.me?.coachSports?.length?state.me.coachSports:['tennis','padel'];return `<div class="content"><h1 class="page-title">Редактировать тренировку</h1><form id="edit-training-form" class="edit-listing"><div class="form-card"><label class="field">Вид спорта<select name="sport">${allowed.map(v=>selectedOption(v,t.sport,v==='tennis'?'Теннис':'Падел')).join('')}</select></label><label class="field">Корт<select name="courtId" required>${courtOptions(t.sport,t.courtId)}</select></label><label class="field">Формат<select name="format">${selectedOption('individual',t.format,'Индивидуальная')}${selectedOption('split',t.format,'Сплит')}${selectedOption('group',t.format,'Группа')}</select></label><label class="field" id="edit-group-seats" ${t.format==='group'?'':'hidden'}>Игроков в группе<select name="seats">${[3,4,5,6].map(v=>selectedOption(v,t.seats,v+' человека')).join('')}</select></label><div class="row"><label class="field">NTRP от<select name="ntrpMin">${selectedOption('',t.ntrpMin??'','Без уровня')}${levelOptions(t.ntrpMin,'tennis')}</select></label><label class="field">NTRP до<select name="ntrpMax">${selectedOption('',t.ntrpMax??'','Без уровня')}${levelOptions(t.ntrpMax,'tennis')}</select></label></div><div class="row"><label class="field">Дата<input type="date" name="date" value="${dayKey(t.startsAt)}" required></label><label class="field">Время<input type="time" name="time" value="${hour(t.startsAt)}" required></label></div><div class="row"><label class="field">Длительность<select name="duration">${[60,90,120].map(v=>selectedOption(v,t.duration,v+' мин')).join('')}</select></label><label class="field">₽ / чел.<input type="number" name="price" min="0" max="100000" value="${t.price}" required></label></div><label class="approval-choice"><input type="checkbox" name="requiresApproval" ${t.requiresApproval?'checked':''}> С подтверждением тренера</label><label class="field">Описание<textarea name="note" maxlength="240">${esc(t.note||'')}</textarea></label></div><button class="button" type="submit">Сохранить изменения</button></form></div>`;}
function peoplePage(coachesOnly=false){return `<div class="content subpage"><h1 class="page-title">${coachesOnly?'Тренера':'Игроки и тренеры'}</h1><p class="lead">${coachesOnly?'Зарегистрированные тренеры Tennis GO. Откройте профиль или напишите тренеру.':'Зарегистрированные пользователи Tennis GO.'}</p><form id="people-search-form" class="search-panel"><label class="field">Поиск по имени<input name="q" value="${esc(state.peopleQuery)}" placeholder="Имя ${coachesOnly?'тренера':'игрока или тренера'}"></label><button class="button light" type="submit">Найти</button></form><div class="results-head"><strong>${coachesOnly?'Тренеры':'Пользователи'}</strong><span>${state.people.length} показано</span></div>${state.people.length?state.people.map(u=>`<article class="card person-card"><span class="avatar">${avatar(u)}</span><span class="person-info"><strong>${esc(u.name)}</strong><small>${u.role==='coach'?'Тренер':'Игрок'} · ${esc(u.city||'Краснодар')}</small></span><span class="person-actions"><button class="small-btn outline" data-user="${esc(u.id)}">Профиль</button><button class="small-btn" data-direct="${esc(u.id)}" data-name="${esc(u.name)}">Написать</button></span></article>`).join(''):`<div class="card empty">${coachesOnly?'Тренеров по запросу пока нет.':'Пользователей по запросу пока нет.'}</div>`}${state.peopleMore?'<button class="button light" data-more-people>Показать ещё</button>':''}</div>`;}
function inboxPage(){return `<div class="content subpage"><h1 class="page-title">Чаты ${state.unread?`<span class="inbox-counter">${state.unread}</span>`:''}</h1><p class="lead">Ваши диалоги с игроками и тренерами.</p>${state.inbox.length?state.inbox.map(t=>`<button class="card inbox-thread ${t.unread?'has-unread':''}" data-inbox-thread="${esc(t.key)}"><span class="avatar">${avatar({name:t.peerName,avatarId:t.peerAvatarId,photoData:t.peerPhotoData})}</span><span class="inbox-thread-body"><strong>${esc(t.peerName)}</strong><small>${esc(t.title)}</small><span>${esc(t.lastMessage)}</span></span>${t.unread?`<b class="unread-pill">${t.unread}</b>`:''}</button>`).join(''):'<div class="card empty"><strong>Диалогов пока нет</strong><p>Откройте раздел «Люди» или объявление и нажмите «Написать».</p></div>'}</div>`;}
function chatMessages(c){return c.messages.length?c.messages.map(m=>`<div class="chat-bubble ${m.senderId===state.me.id?'mine':''}">${esc(m.body)}<small>${day(m.createdAt)} · ${hour(m.createdAt)}</small></div>`).join(''):'<p class="muted">Сообщений пока нет. Напишите первым.</p>';}
function chatPage(){const c=state.chat;if(!c)return '';const title=c.kind==='direct'?'Личный чат':c.kind==='game'?'Игра':'Тренировка';return `<div class="content subpage"><h1 class="page-title">Сообщения · ${title}</h1>${c.peerId?`<p class="lead">${esc(c.peerName||'Автор объявления')}</p><div class="chat-messages">${chatMessages(c)}</div><button class="text-btn" data-chat-refresh>↻ Обновить сообщения</button><form id="chat-form" class="chat-form"><label class="field">Сообщение<textarea name="message" maxlength="500" required placeholder="Напишите сообщение"></textarea></label><button class="button" type="submit">Отправить</button></form>`:`<p class="lead">Выберите диалог по этому объявлению.</p>${c.threads?.length?c.threads.map(p=>`<button class="participant-row" data-chat-peer="${esc(p.id)}"><span class="avatar">${avatar(p)}</span><strong>${esc(p.name)}</strong><span class="participant-next">Открыть →</span></button>`).join(''):'<div class="card empty">Пока никто не написал.</div>'}<button class="text-btn" data-chat-refresh>↻ Обновить диалоги</button>`}</div>`;}

function ratingTiles(u){return `<div class="rating-pair">${['tennis','padel'].map(sport=>{const r=u.ratings?.[sport]||{rating:1500,matches:0,wins:0,losses:0};return `<div class="rating-box"><span>${sport==='tennis'?'🎾 Теннис':'Падел'} · Tennis GO</span><strong>${Math.round(r.rating)}</strong><small>${r.matches<5?'Предварительный · ':''}${r.matches} матчей · ${r.wins} побед · ${r.losses} поражений</small></div>`;}).join('')}</div>`;}
function comingSoon(title){return `<div class="content subpage"><div class="card empty coming-soon"><div class="icon">🎾</div><strong>${title}</strong><p class="muted">Раздел находится в разработке.</p></div></div>`;}
function leaderboardPage(){return `<div class="content subpage"><h2 class="page-title">Рейтинг Tennis GO</h2><p class="lead">Только подтверждённые матчи. NTRP здесь не учитывается.</p><div class="filters"><button class="chip ${state.leaderboardSport==='tennis'?'active':''}" data-ranking-sport="tennis">Теннис</button><button class="chip ${state.leaderboardSport==='padel'?'active':''}" data-ranking-sport="padel">Падел</button></div>${state.leaderboard.length?`<div class="card leaderboard"><div class="leaderboard-head"><span>Место · Игрок</span><span>Рейтинг / матчей</span></div>${state.leaderboard.map((u,i)=>`<button class="leaderboard-row" data-user="${esc(u.id)}"><span class="leaderboard-position">${i+1}</span><span class="avatar">${avatar(u)}</span><span class="leaderboard-name">${esc(u.name)}<small>${esc(u.city)}${u.matches<5?' · предварительный':''}</small></span><span class="leaderboard-score">${Math.round(u.rating)}<small>${u.matches} ${matchesWord(u.matches)}</small></span></button>`).join('')}</div>`:'<div class="card empty"><strong>Пока нет рейтинговых матчей</strong><p class="muted">Таблица заполнится после подтверждения результатов.</p></div>'}</div>`;}
const communityResources=[['Федерация тенниса России','Новости, календарь и правила соревнований','https://tennis-russia.ru/'],['Российский теннисный тур','Новости и календарь российских турниров','https://tennis-russia.ru/rtt/about/novosti-rtt/'],['ФТР · Telegram','Официальный канал федерации: новости и результаты','https://t.me/rustennisRTF'],['Федерация падела России','Турниры, правила и события по паделу','https://federationpadel.ru/'],['ITF · Правила тенниса','Официальные правила и регламенты','https://www.itftennis.com/en/about-us/governance/rules-and-regulations/'],['ATP Tour','Мировой мужской тур и рейтинг','https://www.atptour.com/en/rankings/singles']];
function resourcesPage(){return `<div class="content subpage"><h2 class="page-title">Community</h2><p class="lead">Полезные теннисные ресурсы. Ссылки откроются вне приложения.</p>${communityResources.map(([name,description,url])=>`<a class="card resource-card" href="${url}" target="_blank" rel="noopener noreferrer"><strong>${esc(name)} ↗</strong><small>${esc(description)}</small></a>`).join('')}</div>`;}
function marathonNewsCard(){const m=state.marathon;return m?`<article class="card marathon-news"><img src="/assets/tennis-go-marathon-court.png" alt="Теннисный мяч на корте" loading="lazy"><div><span class="eyebrow">СОБЫТИЯ TENNIS GO</span><h3>${esc(m.title)}</h3><p>Сыграйте ${m.goal} подтверждённых рейтинговых матчей за месяц. Приз — туба теннисных мячей.</p><button class="small-btn" data-page="event-marathon">Правила и прогресс →</button></div></article>`:'<div class="card empty">Новости появятся скоро.</div>';}
function newsPage(){return `<div class="content subpage"><h1 class="page-title">Новости</h1><p class="lead">Новости и события Tennis GO.</p>${state.me?.isAdmin?`<form id="news-form" class="form-card"><h2>Опубликовать новость</h2><label class="field">Заголовок<input name="title" maxlength="120" minlength="5" required placeholder="Что нового?"></label><label class="field">Текст новости<textarea name="body" maxlength="2000" minlength="10" required placeholder="Расскажите участникам о событии"></textarea></label><button class="button" type="submit">Опубликовать и уведомить всех</button></form>`:''}${state.news.map(item=>`<article class="card news-item"><small>${day(item.publishedAt)} · ${hour(item.publishedAt)}</small><h2>${esc(item.title)}</h2><p>${esc(item.body).replace(/\n/g,'<br>')}</p>${state.me?.isAdmin?(state.confirmModeration==='news:'+item.id?`<div class="notice">Удалить новость?</div><button class="small-btn cancel-listing" data-admin-confirm="news:${esc(item.id)}">Да, удалить</button><button class="small-btn outline" data-admin-dismiss>Отмена</button>`:`<button class="small-btn outline" data-admin-ask="news:${esc(item.id)}">Удалить</button>`):''}</article>`).join('')}${marathonNewsCard()}</div>`;}
function eventsPage(){return `<div class="content subpage"><h2 class="page-title">Мероприятия</h2><p class="lead">Актуальные события для игроков.</p>${marathonNewsCard()}</div>`;}
function communityPage(){const tabs=[['people','Люди'],['rating','Рейтинг'],['events','Мероприятия'],['resources','Community']];const page=state.communityTab==='rating'?leaderboardPage():state.communityTab==='events'?eventsPage():state.communityTab==='resources'?resourcesPage():peoplePage();return `<div class="content subpage"><h1 class="page-title">Сообщество</h1><div class="community-switch" aria-label="Разделы сообщества">${tabs.map(([id,label])=>`<button data-community="${id}" class="${state.communityTab===id?'active':''}">${label}</button>`).join('')}</div></div>`+page;}
function playPage(){const page=state.playView==='training'?training():state.playView==='tournaments'?comingSoon('Турниры'):state.playView==='camps'?comingSoon('Camp'):gamesPage();const tabs=[['games','Игры'],['training','Тренировки'],['tournaments','Турниры'],['camps','Camp']];return page.replace('<div class="content subpage">',`<div class="content subpage"><h1 class="play-title">Играть</h1><div class="play-switch" aria-label="Вид события">${tabs.map(([id,label])=>`<button data-play-view="${id}" class="${state.playView===id?'active':''}" aria-pressed="${state.playView===id}">${label}</button>`).join('')}</div>`);}
function notificationsPage(){return `<div class="content subpage"><h1 class="page-title">Уведомления</h1>${state.config.botUsername?`<div class="notice">Чтобы получать новости, игры и тренировки в Telegram, разрешите сообщения боту или откройте его и нажмите /start.</div><button class="button light" data-enable-push>Разрешить сообщения бота в Telegram</button><a class="bot-start-link" href="https://t.me/${esc(state.config.botUsername.replace(/^@/,''))}?start=notifications" target="_blank" rel="noopener noreferrer">Открыть бота →</a>`:''}${state.notifications.length?state.notifications.map(n=>`<div class="card notification-row"><span>${esc(n.body)}</span><small>${day(n.createdAt)} · ${hour(n.createdAt)}</small></div>`).join(''):'<div class="card empty">Пока нет уведомлений.</div>'}</div>`;}
function render(){if(state.loading){app.innerHTML='<div class="splash">🎾 Tennis GO</div>';return;}const blocked=!!state.me?.blockedAt,registering=!state.me?.registered&&!blocked,club=state.me?.role==='club'&&!state.me?.isAdmin&&!registering&&!blocked,page=blocked?'<div class="content subpage"><h1 class="page-title">Доступ ограничен</h1><p class="notice">Ваш аккаунт заблокирован администратором. Для уточнения напишите в Telegram @RVL233.</p></div>':registering?registration():club?(state.form==='edit-club'?clubRegistrationPage(true):clubPage()):state.form==='court-booking'?courtBookingPage():state.form==='courts'?courtsPage():state.form==='coaches'?peoplePage(true):state.form==='news'?newsPage():state.form==='event-marathon'?marathonPage():state.form==='admin-clubs'?adminClubsPage():state.form==='admin'?adminPage():state.form==='admin-preview'?`<div class="content subpage"><h1 class="page-title">Просмотр меню ролей</h1>${adminRolePreviewPage()}</div>`:state.form==='admin-calendar'?adminCalendarPage():state.form==='admin-club-form'?adminClubForm():state.chat?chatPage():state.form==='edit-game'?editGamePage():state.form==='edit-training'?editTrainingPage():state.userProfile?publicProfile(state.userProfile):state.trainingDetail?trainingDetail(state.trainingDetail):state.detail?gameDetail(state.detail):state.form==='create'?createPage():state.form==='create-training'?createTrainingPage():state.form==='edit-profile'?profileEditor():state.form==='notifications'?notificationsPage():({home,play:playPage,chat:inboxPage,games:gamesPage,training,community:communityPage,profile})[state.tab]?.()||home();const showBack=!blocked&&(registering||club&&!!state.form||!!state.chat||!!state.userProfile||!!state.trainingDetail||!!state.detail||!!state.form||state.tab!=='home');app.innerHTML=`<main class="app">${logo()}${showBack?'<div class="global-back"><button data-back aria-label="Вернуться на предыдущий экран">← Назад</button></div>':''}${page}${registering||club||blocked?'':nav()}</main>`;tg?.BackButton?.[showBack?'show':'hide']?.();}
function snapshot(){return {tab:state.tab,playView:state.playView,form:state.form,detailId:state.detail?.id||null,trainingId:state.trainingDetail?.id||null,userProfile:state.userProfile,chat:state.chat};}
function pushView(){state.history.push(snapshot());}
function back(){if(!state.me?.registered){if(state.registrationStep>1){state.registrationStep--;render();}else if(tg?.close)tg.close();else toast('Это первый экран');return;}const previous=state.history.pop();if(previous){state.tab=previous.tab;state.playView=previous.playView||state.playView;state.form=previous.form;state.detail=previous.detailId?state.games.find(g=>g.id===previous.detailId)||null:null;state.trainingDetail=previous.trainingId?state.trainings.find(t=>t.id===previous.trainingId)||null:null;state.userProfile=previous.userProfile;state.chat=previous.chat||null;state.confirmCancel=null;render();return;}if(state.form||state.detail||state.trainingDetail||state.userProfile||state.chat||state.tab!=='home'){state.form='';state.detail=null;state.trainingDetail=null;state.userProfile=null;state.chat=null;state.tab='home';render();return;}if(tg?.close)tg.close();else toast('Это главный экран');}
function openGame(id){pushView();state.detail=state.games.find(g=>g.id===id)||null;state.trainingDetail=null;state.userProfile=null;state.chat=null;state.form='';render();}
function openTraining(id){const found=state.trainings.find(t=>t.id===id);if(!found)return toast('Тренировка не найдена');pushView();state.trainingDetail=found;state.detail=null;state.userProfile=null;state.chat=null;state.form='';render();}
async function openChat(kind,id,peerId=null){const listing=kind==='game'?state.games.find(x=>x.id===id):state.trainings.find(x=>x.id===id);if(!listing)throw Error('Объявление не найдено');const authorId=kind==='game'?listing.creatorId:listing.coachId,own=authorId===state.me.id;const peer=own?peerId:authorId;let data=own&&!peer?await api(`/chats/${kind}/${id}`):await api(`/chats/${kind}/${id}/${peer}`);pushView();state.tab='chat';state.chat={kind,id,authorId,peerId:peer||null,peerName:own?state.chat?.threads?.find(x=>x.id===peer)?.name||'Участник':kind==='training'?listing.coachName:'Автор игры',messages:data.messages||[],threads:data.threads||[]};state.form='';render();}
async function refreshChat(silent=false){const c=state.chat;if(!c)return;const data=await api(c.kind==='direct'?`/direct/${c.peerId}`:`/chats/${c.kind}/${c.id}${c.peerId?'/'+c.peerId:''}`);if(state.chat!==c)return;const before=JSON.stringify(c.messages);c.messages=data.messages||[];c.threads=data.threads||[];if(silent&&c.peerId){if(before!==JSON.stringify(c.messages)){const box=document.querySelector('.chat-messages');if(box){box.innerHTML=chatMessages(c);box.scrollTop=box.scrollHeight;}}}else render();}
async function openDirect(id,name){const data=await api('/direct/'+encodeURIComponent(id));pushView();state.tab='chat';state.chat={kind:'direct',id,peerId:id,peerName:name||data.peer?.name||'Пользователь',messages:data.messages||[],threads:[]};state.form='';render();loadInbox(false).catch(()=>{});}
async function openUser(id){const data=await api('/users/'+encodeURIComponent(id));pushView();state.userProfile=data.user;state.form='';render();}
function startAt(form){const d=form.get('date'),t=form.get('time');return new Date(`${d}T${t}:00+03:00`).toISOString();}
async function doAction(action){const g=state.detail;if(!g)return;if(action==='share'){const link=state.config.botUsername?`https://t.me/${state.config.botUsername}?startapp=game_${g.id}`:`${location.origin}/?game=${g.id}`;const msg=`🎾 ${g.sport==='tennis'?'Теннис':'Падел'} · ${day(g.startsAt)} ${hour(g.startsAt)} · ${g.venue}. Присоединяйся: ${link}`;if(tg?.initData&&state.config.botUsername){tg.openTelegramLink(`https://t.me/share/url?url=${encodeURIComponent(link)}&text=${encodeURIComponent(msg)}`);}else{await navigator.clipboard.writeText(msg);toast('Приглашение скопировано');}return;}
  const wasPending=g.requestStatus==='pending',data=await api(`/games/${g.id}/${action}`,'POST');state.detail=data.game;await refresh();state.detail=state.games.find(x=>x.id===g.id)||data.game;render();toast(({join:state.detail?.requestStatus==='pending'?'Заявка отправлена организатору':'Вы в игре!',leave:wasPending?'Заявка отменена':'Вы вышли из игры',attend:'Ожидаем подтверждения соперника','contest-absence':'Неявка оспорена','confirm-attendance':'Встреча подтверждена',confirm:state.detail?.resultConfirmed?'Результат подтверждён, рейтинг обновлён':'Счёт подтверждён, ожидаем остальных'})[action]);}
app.addEventListener('click',async e=>{const el=e.target.closest('[data-event-step],[data-event-go],[data-preview-role],[data-preview-tab],[data-admin-tab],[data-admin-block],[data-admin-unblock],[data-admin-ask],[data-admin-confirm],[data-admin-dismiss],[data-admin-calendar],[data-admin-club-edit],[data-admin-club-create],[data-event-action],[data-book-court],[data-club-decision],[data-cancel-court-booking],[data-play-view],[data-enable-push],[data-locate],[data-training-complete],[data-notifications],[data-community],[data-ranking-sport],[data-request-decision],[data-direct],[data-inbox-thread],[data-more-people],[data-chat],[data-chat-peer],[data-chat-refresh],[data-edit],[data-cancel],[data-confirm-cancel],[data-dismiss-cancel],[data-role],[data-avatar],[data-register-back],[data-my-level],[data-rating-only],[data-training-action],[data-training],[data-user],[data-tab],[data-page],[data-filter],[data-when],[data-available],[data-reset-filters],[data-game],[data-action],[data-back],[data-remove-photo]');if(!el)return;try{
 if(el.dataset.eventStep){moveEvent(Number(el.dataset.eventStep));}
 else if(el.dataset.eventGo!==undefined){state.eventIndex=Number(el.dataset.eventGo);render();}
 else if(el.dataset.previewRole){state.previewRole=el.dataset.previewRole;state.previewTab='home';render();}
 else if(el.dataset.previewTab){state.previewTab=el.dataset.previewTab;render();}
 else if(el.dataset.eventAction==='play'){pushView();state.tab='play';state.playView='games';state.ratingOnly=true;state.form='';state.detail=null;render();}
 else if(el.dataset.bookCourt){pushView();state.bookingCourtId=el.dataset.bookCourt;state.form='court-booking';render();}
 else if(el.dataset.playView){state.playView=el.dataset.playView;render();}
 else if(el.dataset.adminTab){await loadAdmin(el.dataset.adminTab);render();}
 else if(el.dataset.adminBlock){state.pendingBlock=el.dataset.adminBlock;render();}
 else if(el.dataset.adminUnblock){await api('/admin/users/'+encodeURIComponent(el.dataset.adminUnblock)+'/unblock','POST');await loadAdmin('users');render();toast('Пользователь разблокирован');}
 else if(el.dataset.adminAsk){state.confirmModeration=el.dataset.adminAsk;render();}
 else if(el.hasAttribute('data-admin-dismiss')){state.confirmModeration=null;state.pendingBlock=null;render();}
 else if(el.dataset.adminConfirm){const [kind,type,id]=el.dataset.adminConfirm.split(':');if(kind==='message')await api('/admin/messages/'+type+'/'+encodeURIComponent(id),'DELETE');else if(kind==='news')await api('/admin/news/'+encodeURIComponent(type),'DELETE');else if(kind==='game'||kind==='training')await api('/'+(kind==='game'?'games':'trainings')+'/'+encodeURIComponent(type),'DELETE');state.confirmModeration=null;await refresh();if(state.form==='admin')await loadAdmin(state.adminTab);render();toast('Удалено');}
 else if(el.dataset.adminCalendar){pushView();state.adminClubId=el.dataset.adminCalendar;state.clubDate=dayKey(Date.now());state.adminCalendar=(await api('/admin/clubs/'+encodeURIComponent(state.adminClubId)+'/calendar?date='+state.clubDate)).reservations;state.form='admin-calendar';render();}
 else if(el.dataset.adminClubEdit){pushView();state.adminClubId=el.dataset.adminClubEdit;state.clubPhotoData=state.adminClubs.find(c=>c.ownerId===state.adminClubId)?.photoData||null;state.form='admin-club-form';render();}
 else if(el.hasAttribute('data-admin-club-create')){pushView();state.adminClubId=null;state.clubPhotoData=null;state.form='admin-club-form';render();}
 else if(el.dataset.clubDecision){await api(`/admin/clubs/${encodeURIComponent(el.dataset.clubId)}/${el.dataset.clubDecision}`,'POST');state.adminClubs=(await api('/admin/clubs')).clubs;render();toast(el.dataset.clubDecision==='approve'?'Клуб подтверждён':'Заявка отклонена');}
 else if(el.dataset.cancelCourtBooking){await api('/court-bookings/'+el.dataset.cancelCourtBooking,'DELETE');await refresh();render();toast('Бронирование отменено');}
 else if(el.hasAttribute('data-locate')){requestLocation();}
 else if(el.hasAttribute('data-enable-push')){if(tg?.requestWriteAccess)tg.requestWriteAccess(allowed=>toast(allowed?'Уведомления бота разрешены':'Откройте бота и нажмите /start'));else if(state.config.botUsername)tg?.openTelegramLink?.(`https://t.me/${state.config.botUsername.replace(/^@/,'')}?start=notifications`);else toast('Откройте бота и нажмите /start');}
 else if(el.dataset.trainingComplete){const id=el.dataset.trainingComplete;await api(`/trainings/${id}/complete`,'POST');await refresh();state.trainingDetail=state.trainings.find(t=>t.id===id);render();toast('Тренировка подтверждена');}
 else if(el.hasAttribute('data-notifications')){pushView();state.form='notifications';state.detail=null;state.trainingDetail=null;state.userProfile=null;state.chat=null;await api('/notifications/read','POST');state.notificationUnread=0;render();}
 else if(el.dataset.community){state.communityTab=el.dataset.community;if(state.communityTab==='people'&&state.peopleMode!=='all'){state.peopleMode='all';state.people=[];state.peopleQuery='';state.peopleOffset=0;}if(state.communityTab==='people'&&!state.people.length)await loadPeople(true);if(state.communityTab==='rating')await loadLeaderboard();render();}
 else if(el.dataset.rankingSport){state.leaderboardSport=el.dataset.rankingSport;await loadLeaderboard();}
 else if(el.dataset.requestDecision){const kind=el.dataset.requestKind,id=el.dataset.requestId,group=kind==='game'?'games':'trainings';await api(`/${group}/${id}/requests/${encodeURIComponent(el.dataset.requestUser)}/${el.dataset.requestDecision}`,'POST');await refresh();if(kind==='game')state.detail=state.games.find(g=>g.id===id)||null;else state.trainingDetail=state.trainings.find(t=>t.id===id)||null;render();toast(el.dataset.requestDecision==='approve'?'Заявка подтверждена':'Заявка отклонена');}
 else if(el.dataset.direct){await openDirect(el.dataset.direct,el.dataset.name);}
 else if(el.dataset.inboxThread){const t=state.inbox.find(x=>x.key===el.dataset.inboxThread);if(!t)return;if(t.kind==='direct')await openDirect(t.peerId,t.peerName);else await openChat(t.kind,t.listingId,t.peerId);}
 else if(el.hasAttribute('data-more-people')){await loadPeople();}
 else if(el.dataset.chat){const [kind,id]=el.dataset.chat.split(':');await openChat(kind,id);}
 else if(el.dataset.chatPeer){await openChat(state.chat.kind,state.chat.id,el.dataset.chatPeer);}
 else if(el.hasAttribute('data-chat-refresh')){await refreshChat();}
 else if(el.dataset.edit){const [kind,id]=el.dataset.edit.split(':');pushView();state.editTarget={kind,id};state.form=kind==='game'?'edit-game':'edit-training';state.detail=null;state.trainingDetail=null;state.chat=null;render();}
 else if(el.dataset.cancel){state.confirmCancel=el.dataset.cancel;render();}
 else if(el.hasAttribute('data-dismiss-cancel')){state.confirmCancel=null;render();}
 else if(el.dataset.confirmCancel){const [kind,id]=el.dataset.confirmCancel.split(':');await api(`/${kind==='game'?'games':'trainings'}/${id}`,'DELETE');await refresh();state.confirmCancel=null;state.detail=kind==='game'?state.games.find(x=>x.id===id):null;state.trainingDetail=kind==='training'?state.trainings.find(x=>x.id===id):null;render();toast('Объявление отменено');}
 else if(el.dataset.role){state.registrationRole=el.dataset.role;state.clubPhotoData=null;state.registrationStep=2;state.registrationDraft=null;state.profilePhotoData=state.me?.photoData||null;state.avatarId=state.me?.avatarId||null;render();}
 else if(el.hasAttribute('data-register-back'))back();
 else if(el.dataset.avatar){state.avatarId=el.dataset.avatar;state.profilePhotoData=null;document.querySelector('#photo-preview').innerHTML=tennisAvatar(state.avatarId);document.querySelector('#profile-photo-input').value='';document.querySelectorAll('[data-avatar]').forEach(button=>{button.classList.toggle('selected',button.dataset.avatar===state.avatarId);button.setAttribute('aria-pressed',button.dataset.avatar===state.avatarId);});}
 else if(el.dataset.trainingAction){await api(`/trainings/${el.dataset.trainingId}/${el.dataset.trainingAction}`,'POST');await refresh();if(state.trainingDetail)state.trainingDetail=state.trainings.find(t=>t.id===el.dataset.trainingId)||null;render();toast(el.dataset.trainingAction==='join'?(state.trainingDetail?.requestStatus==='pending'?'Заявка отправлена тренеру':'Вы записаны на тренировку'):'Запись отменена');}
 else if(el.dataset.user)await openUser(el.dataset.user);
 else if(el.dataset.training)openTraining(el.dataset.training);
 else if(el.dataset.tab){if(el.dataset.tab==='community'&&state.peopleMode!=='all'){state.peopleMode='all';state.people=[];state.peopleQuery='';state.peopleOffset=0;}if(el.dataset.tab==='community'&&state.communityTab==='people'&&!state.people.length)await loadPeople(true);if(el.dataset.tab==='chat')await loadInbox(false);if(el.dataset.tab==='community'&&state.communityTab==='rating')await loadLeaderboard();const target=['games','training'].includes(el.dataset.tab)?'play':el.dataset.tab;if(state.tab!==target||state.detail||state.trainingDetail||state.userProfile||state.form)pushView();if(['games','training'].includes(el.dataset.tab))state.playView=el.dataset.tab;state.tab=target;state.detail=null;state.trainingDetail=null;state.userProfile=null;state.chat=null;state.form='';render();}
 else if(el.dataset.page){pushView();state.form=el.dataset.page;state.detail=null;state.trainingDetail=null;state.userProfile=null;if(state.form==='coaches'){state.peopleMode='coach';state.people=[];state.peopleQuery='';state.peopleOffset=0;await loadPeople(true);}if(state.form==='admin-clubs')state.adminClubs=(await api('/admin/clubs')).clubs;if(state.form==='admin')await loadAdmin();if(state.form==='edit-club')state.clubPhotoData=state.me.club?.photoData||null;if(state.form==='edit-profile'){state.profilePhotoData=state.me.photoData||null;state.avatarId=state.me.avatarId||null;}render();}
 else if(el.hasAttribute('data-remove-photo')){state.profilePhotoData=null;document.querySelector('#photo-preview').innerHTML=avatar({name:state.me.name,avatarId:state.avatarId});document.querySelector('#profile-photo-input').value='';document.querySelectorAll('[data-avatar]').forEach(button=>button.classList.toggle('selected',button.dataset.avatar===state.avatarId));}
 else if(el.dataset.filter){state.filter=el.dataset.filter;state.courts=state.courts.filter(id=>state.catalog.courts.some(c=>c.id===id&&(state.filter==='all'||c.sport===state.filter)));render();}
 else if(el.dataset.when){state.when=el.dataset.when;render();}
 else if(el.hasAttribute('data-my-level')){if(state.me?.ntrpLevel==null){toast('Укажите свой NTRP в профиле');return;}state.myLevelOnly=!state.myLevelOnly;render();}
 else if(el.hasAttribute('data-rating-only')){state.ratingOnly=!state.ratingOnly;render();}
 else if(el.hasAttribute('data-available')){state.availableOnly=!state.availableOnly;render();}
 else if(el.hasAttribute('data-reset-filters')){state.filter='all';state.when='all';state.courts=[];state.genderFilter='all';state.ratingOnly=false;state.myLevelOnly=false;state.availableOnly=false;render();}
 else if(el.dataset.game)openGame(el.dataset.game);
 else if(el.hasAttribute('data-back'))back();
 else if(el.dataset.action)await doAction(el.dataset.action);
 }catch(err){toast(err.message);}});
app.addEventListener('keydown',e=>{if(e.target.matches?.('.clickable-game,.compact-game,.compact-training')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();if(e.target.dataset.game)openGame(e.target.dataset.game);else if(e.target.dataset.training)openTraining(e.target.dataset.training);}});
let eventSwipe=null;
app.addEventListener('touchstart',e=>{if(e.target.closest?.('[data-events-carousel]')&&e.touches?.length===1)eventSwipe={x:e.touches[0].clientX,y:e.touches[0].clientY};},{passive:true});
app.addEventListener('touchend',e=>{if(!eventSwipe||!e.target.closest?.('[data-events-carousel]'))return;const dx=e.changedTouches[0].clientX-eventSwipe.x,dy=e.changedTouches[0].clientY-eventSwipe.y;eventSwipe=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.2)moveEvent(dx<0?1:-1);},{passive:true});
app.addEventListener('wheel',e=>{if(e.target.closest?.('[data-events-carousel]')&&Math.abs(e.deltaX)>35&&Math.abs(e.deltaX)>Math.abs(e.deltaY))moveEvent(e.deltaX>0?1:-1);},{passive:true});
app.addEventListener('keydown',e=>{if(e.target.closest?.('[data-events-carousel]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();moveEvent(e.key==='ArrowRight'?1:-1);}});
app.addEventListener('change',async e=>{if(e.target.id==='court-city-filter'){state.courtCity=e.target.value;render();return;}if(e.target.id==='court-sport-filter'){state.courtSport=e.target.value;render();return;}if(e.target.id==='club-photo-input'){if(!e.target.files?.[0])return;try{state.clubPhotoData=await imageData(e.target.files[0],true);document.querySelector('#club-photo-preview').innerHTML=`<img src="${esc(state.clubPhotoData)}" alt="Фото клуба">`;}catch(err){toast(err.message);}return;}if(e.target.id==='admin-calendar-date'){state.clubDate=e.target.value;state.adminCalendar=(await api('/admin/clubs/'+encodeURIComponent(state.adminClubId)+'/calendar?date='+state.clubDate)).reservations;render();return;}if(e.target.id==='club-calendar-date'){state.clubDate=e.target.value;await refresh();render();return;}if(e.target.id==='game-city-filter'){state.cityFilter=e.target.value;await loadWeather();render();return;}if(e.target.id==='training-city-filter'){state.trainingCity=e.target.value;await loadWeather();render();return;}if(e.target.id==='profile-photo-input'){if(!e.target.files?.[0])return;try{state.profilePhotoData=await imageData(e.target.files[0]);document.querySelector('#photo-preview').innerHTML=`<img src="${esc(state.profilePhotoData)}" alt="Фото профиля">`;document.querySelectorAll('[data-avatar]').forEach(button=>{button.classList.remove('selected');button.setAttribute('aria-pressed','false');});}catch(err){toast(err.message);}return;}if(e.target.name==='ntrpLevel'&&e.target.closest('#profile-form,#registration-form')){document.querySelector('#profile-level-description').textContent=e.target.value==='unknown'?'Приложение поставит NTRP 1.0. Позже уровень можно изменить в профиле.':levelDescriptions.tennis[e.target.value]||'Выберите уровень, чтобы прочитать описание навыков.';return;}if(e.target.name==='role'&&e.target.closest('#profile-form')){const coach=e.target.value==='coach',card=document.querySelector('#coach-years-card'),input=card.querySelector('input'),ntrp=document.querySelector('#profile-ntrp-card'),level=ntrp.querySelector('select[name=ntrpLevel]');card.hidden=!coach&&!state.me?.isAdmin;input.required=coach;ntrp.hidden=coach;level.required=!coach;document.querySelector('#coach-sports-card').hidden=!coach&&!state.me?.isAdmin;document.querySelector('textarea[name=about]').placeholder=coach?'Расскажите о вашем тренерском опыте':'Как часто играете, что ищете в приложении';return;}if(e.target.name==='sport'&&e.target.closest('#edit-training-form,#edit-game-form')){e.target.form.elements.courtId.innerHTML=courtOptions(e.target.value);return;}if(e.target.name==='format'&&e.target.closest('#edit-training-form')){document.querySelector('#edit-group-seats').hidden=e.target.value!=='group';return;}if(e.target.name==='sport'&&e.target.closest('#training-form')){e.target.form.elements.courtId.innerHTML=courtOptions(e.target.value);return;}if(e.target.name==='format'&&e.target.closest('#training-form')){document.querySelector('#group-seats').hidden=e.target.value!=='group';return;}if(e.target.id==='gender-filter'){state.genderFilter=e.target.value;render();return;}if(e.target.dataset?.gameCourt){const id=e.target.dataset.gameCourt;state.courts=e.target.checked?[...new Set([...state.courts,id])]:state.courts.filter(c=>c!==id);e.target.closest('.game-courts').querySelector('summary').textContent='Корты · '+(state.courts.length?'выбрано '+state.courts.length:'все');const results=document.querySelector('#game-results');if(results)results.innerHTML=gameResults();return;}const form=e.target.closest('#create-form');if(!form)return;if(e.target.name==='sport')updateCreateChoices(form);else if(['rating','seats'].includes(e.target.name))syncGameFormat(form);else if(['courtId','levelMin','levelMax'].includes(e.target.name))updateCreateHints(form);});
app.addEventListener('change',e=>{if(e.target.id==='training-sport-filter')state.trainingSport=e.target.value;else if(e.target.id==='training-gender-filter')state.trainingGender=e.target.value;else if(e.target.id==='training-format-filter')state.trainingFormat=e.target.value;else if(e.target.dataset?.trainingCourt){const id=e.target.dataset.trainingCourt;state.trainingCourts=e.target.checked?[...state.trainingCourts,id]:state.trainingCourts.filter(x=>x!==id);e.target.closest('.court-multiselect').querySelector('summary').textContent='Корты · '+(state.trainingCourts.length?'выбрано '+state.trainingCourts.length:'все');}else return;const results=document.querySelector('#training-results');if(results)results.innerHTML=trainingResults();});
app.addEventListener('submit',async e=>{if(!['admin-block-form','admin-user-search','admin-club-form','news-form','create-form','training-form','result-form','absence-form','dispute-form','review-form','profile-form','registration-form','coach-registration-form','edit-game-form','edit-training-form','chat-form','people-search-form','club-registration-form','club-edit-form','court-booking-form'].includes(e.target.id))return;e.preventDefault();const form=new FormData(e.target),button=e.target.querySelector('button[type=submit]');button.disabled=true;try{
 if(e.target.id==='news-form'){await api('/news','POST',{title:form.get('title'),body:form.get('body')});await refresh();render();toast('Новость опубликована, уведомления отправляются');}
 else if(e.target.id==='admin-user-search'){state.adminQuery=String(form.get('q')||'').trim();await loadAdmin('users');render();}
 else if(e.target.id==='admin-block-form'){await api('/admin/users/'+encodeURIComponent(e.target.dataset.userId)+'/block','POST',{reason:form.get('reason')});state.pendingBlock=null;await loadAdmin('users');await refresh();render();toast('Пользователь заблокирован');}
 else if(e.target.id==='admin-club-form'){const payload={clubName:form.get('clubName'),clubAddress:form.get('clubAddress'),city:form.get('city'),clubPhone:form.get('clubPhone'),clubSports:form.getAll('clubSports'),clubSurface:form.get('clubSurface'),opensAt:form.get('opensAt'),closesAt:form.get('closesAt'),hourlyPrice:Number(form.get('hourlyPrice')),clubPhotoData:state.clubPhotoData};if(!payload.clubPhotoData)throw Error('Добавьте фото клуба');await api(state.adminClubId?'/admin/clubs/'+encodeURIComponent(state.adminClubId):'/admin/clubs',state.adminClubId?'PATCH':'POST',payload);await refresh();await loadAdmin('clubs');state.history.pop();state.form='admin';render();toast('Данные клуба сохранены');}
 else if(e.target.id==='club-registration-form'||e.target.id==='club-edit-form'){const payload={role:'club',name:String(form.get('name')||'').trim(),clubName:form.get('clubName'),clubAddress:form.get('clubAddress'),city:form.get('city'),clubPhone:form.get('clubPhone'),clubSports:form.getAll('clubSports'),clubSurface:form.get('clubSurface'),opensAt:form.get('opensAt'),closesAt:form.get('closesAt'),hourlyPrice:Number(form.get('hourlyPrice')),clubPhotoData:state.clubPhotoData};await saveIdentity(payload);toast('Заявка клуба отправлена администратору');}
 else if(e.target.id==='court-booking-form'){const court=state.catalog.courts.find(c=>c.id===form.get('courtId'));if(!court?.clubId)throw Error('Выберите подтверждённый клуб');await api('/court-bookings','POST',{clubId:court.clubId,sport:court.sport,startsAt:startAt(form),duration:Number(form.get('duration'))});await refresh();state.history.pop();state.form='';state.tab='profile';render();toast('Корт забронирован');}
 else if(e.target.id==='absence-form'){const id=state.detail.id;await api(`/games/${id}/report-absence`,'POST',{reason:form.get('reason')});await refresh();state.detail=state.games.find(g=>g.id===id);render();toast('Неявка зафиксирована без изменения рейтинга');}
 else if(e.target.id==='dispute-form'){const id=state.detail.id;await api(`/games/${id}/dispute`,'POST',{reason:form.get('reason')});await refresh();state.detail=state.games.find(g=>g.id===id);render();toast('Спор по счёту отправлен');}
 else if(e.target.id==='review-form'){await api(`/trainings/${state.trainingDetail.id}/review`,'POST',{score:Number(form.get('score')),comment:form.get('comment')});state.trainingDetail.reviewed=true;render();toast('Отзыв опубликован');}
 else if(e.target.id==='people-search-form'){state.peopleQuery=String(form.get('q')||'').trim();await loadPeople(true);}
 else if(e.target.id==='chat-form'){const c=state.chat,data=await api(c.kind==='direct'?`/direct/${c.peerId}`:`/chats/${c.kind}/${c.id}/${c.peerId}`,'POST',{message:form.get('message')});c.messages=data.messages;render();loadInbox(false).catch(()=>{});}
 else if(e.target.id==='edit-game-form'){const id=state.editTarget.id,payload={sport:form.get('sport'),seats:Number(form.get('seats')),kind:form.has('rating')?'rating':'friendly',courtId:form.get('courtId'),startsAt:startAt(form),duration:Number(form.get('duration')),price:Number(form.get('price')),levelMin:Number(form.get('levelMin')),levelMax:Number(form.get('levelMax')),opponentGender:form.get('opponentGender'),requiresApproval:form.has('requiresApproval'),note:form.get('note')};const data=await api(`/games/${id}`,'PATCH',payload);await refresh();state.history.pop();state.form='';state.detail=state.games.find(g=>g.id===id)||data.game;render();toast('Игра обновлена');}
 else if(e.target.id==='edit-training-form'){const id=state.editTarget.id,format=form.get('format'),payload={sport:form.get('sport'),format,seats:format==='individual'?1:format==='split'?2:Number(form.get('seats')),courtId:form.get('courtId'),startsAt:startAt(form),duration:Number(form.get('duration')),ntrpMin:form.get('ntrpMin')?Number(form.get('ntrpMin')):null,ntrpMax:form.get('ntrpMax')?Number(form.get('ntrpMax')):null,requiresApproval:form.has('requiresApproval'),price:Number(form.get('price')),note:form.get('note')};const data=await api(`/trainings/${id}`,'PATCH',payload);await refresh();state.history.pop();state.form='';state.trainingDetail=state.trainings.find(t=>t.id===id)||data.training;render();toast('Тренировка обновлена');}
 else if(e.target.id==='registration-form'){const payload=identityPayload(form);if(!payload.photoData&&!payload.avatarId)throw Error('Загрузите фото или выберите аватарку');if(payload.role==='coach'){if(!payload.coachSports.length)throw Error('Выберите теннис, падел или оба вида спорта');state.registrationDraft=payload;state.registrationStep=3;render();}else await saveIdentity(payload);}
 else if(e.target.id==='coach-registration-form'){await saveIdentity({...state.registrationDraft,coachYears:Number(form.get('coachYears'))});}
 else if(e.target.id==='profile-form'){await saveIdentity(identityPayload(form));}
 else if(e.target.id==='training-form'){const format=form.get('format'),payload={sport:form.get('sport'),format,seats:format==='individual'?1:format==='split'?2:Number(form.get('seats')),courtId:form.get('courtId'),startsAt:startAt(form),duration:Number(form.get('duration')),ntrpMin:form.get('ntrpMin')?Number(form.get('ntrpMin')):null,ntrpMax:form.get('ntrpMax')?Number(form.get('ntrpMax')):null,requiresApproval:form.has('requiresApproval'),price:Number(form.get('price')),note:form.get('note')};if((payload.ntrpMin===null)!==(payload.ntrpMax===null)||payload.ntrpMin!==null&&payload.ntrpMin>payload.ntrpMax)throw Error('Укажите оба значения NTRP: «от» не выше «до»');await api('/trainings','POST',payload);await refresh();state.history.pop();state.form='';state.tab='play';state.playView='training';render();toast('Тренировка опубликована');}
 else if(e.target.id==='create-form'){const payload={sport:form.get('sport'),seats:Number(form.get('seats')),kind:form.has('rating')?'rating':'friendly',courtId:form.get('courtId'),city:'Краснодар',startsAt:startAt(form),duration:Number(form.get('duration')),price:Number(form.get('price')),levelMin:Number(form.get('levelMin')),levelMax:Number(form.get('levelMax')),opponentGender:form.get('opponentGender'),requiresApproval:form.has('requiresApproval'),note:form.get('note')};if(payload.levelMin>payload.levelMax)throw Error('Уровень «От» не может быть выше «До»');const data=await api('/games','POST',payload);await refresh();state.form='';state.tab='play';state.playView='games';openGame(data.game.id);toast('Игра создана · пригласите игроков');}
 else{const id=state.detail.id;const data=await api(`/games/${id}/result`,'POST',{score:form.get('score')});await refresh();state.detail=state.games.find(g=>g.id===id)||data.game;render();toast('Результат отправлен второму игроку');}
 }catch(err){button.disabled=false;toast(err.message);}});
tg?.BackButton?.onClick(back);
(async()=>{try{state.config=await api('/config');state.me=(await api('/me')).user;const params=new URLSearchParams(location.search),param=tg?.initDataUnsafe?.start_param||params.get('tgWebAppStartParam')||params.get('start')||params.get('game');state.pendingGame=param?.startsWith('game_')?param.slice(5):null;if(state.me.registered&&!state.me.blockedAt){await refresh();if(param==='news'){state.form='news';}else if(param?.startsWith('training_')&&state.me.role!=='club'){state.trainingDetail=state.trainings.find(t=>t.id===param.slice(9))||null;}else if(state.pendingGame&&state.me.role!=='club'){try{state.detail=(await api(`/games/${state.pendingGame}`)).game;}catch{toast('Игра по ссылке не найдена');}state.pendingGame=null;}}state.loading=false;render();}catch(err){app.innerHTML=`<main class="app"><div class="content desktop-entry"><h1>Tennis GO</h1><p>${esc(err.message)}</p><p>Откройте бота в Telegram на компьютере или телефоне и нажмите кнопку «Меню» или «Запустить приложение». Обычная ссылка на сайт не передаёт данные Telegram для входа.</p>${state.config.botUsername?`<a class="button" href="https://t.me/${esc(state.config.botUsername.replace(/^@/,''))}" target="_blank" rel="noopener noreferrer">Открыть бота в Telegram →</a>`:''}<p class="hint">Если Telegram для ПК уже открыт, обновите его до актуальной версии и попробуйте кнопку бота ещё раз.</p></div></main>`;}})();

window.setInterval?.(()=>{if(state.me?.registered&&state.me.role!=='club')api('/notifications').then(n=>{const was=state.notificationUnread;state.notifications=n.items||[];state.notificationUnread=n.unread||0;if(was!==state.notificationUnread&&!state.form&&!state.chat)refresh().then(()=>{if(state.detail)state.detail=state.games.find(g=>g.id===state.detail.id)||state.detail;if(state.trainingDetail)state.trainingDetail=state.trainings.find(t=>t.id===state.trainingDetail.id)||state.trainingDetail;render();}).catch(()=>render());}).catch(()=>{});if(state.chat)refreshChat(true).catch(()=>{});if(state.location&&state.geoPolls<10&&state.catalog.courts.some(c=>c.latitude==null)){state.geoPolls++;api('/catalog').then(c=>{state.catalog=c;if(state.tab==='play'||state.detail||state.tab==='home')render();}).catch(()=>{});}if(state.me?.registered&&state.me.role!=='club')loadInbox(false).catch(()=>{});},10000);
window.setInterval?.(()=>{if(state.me?.role==='club'&&!state.form)refresh().then(render).catch(()=>{});if(state.me?.registered&&state.tab==='play'&&state.playView==='games'&&!state.form&&!state.detail&&!state.chat)render();},60000);
